NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Luke'

CHAPTERS = {
    1: {
        1: 'Ker so že mnogi vzeli v roko, da po vrsti uredijo izjavo o teh stvareh, ki se najbolj gotovo verjamejo med nami,',
        2: 'celo kakor so nam jih izročili [tisti], ki so bili od začetka priče in služabniki besede,',
        3: 'se je tudi meni zdelo dobro, od samega začetka imeti popolno razumevanje o vseh stvareh, da tebi, nadvse odlični Teófil, napišem po vrsti,',
        4: 'da lahko spoznaš zanesljivost o teh besedah, o katerih si bil poučen.',
        5: 'V dneh Heroda, judejskega kralja, je bil nek duhovnik, imenovan Zaharija, iz Abíjeve skupine, in njegova žena je bila izmed Aronovih hčera in njeno ime je bilo Elizabeta.',
        6: 'Oba sta bila pravična pred Bogom in sta brez krivde živela po vseh Gospodovih zapovedih in odredbah.',
        7: 'Ker je bila Elizabeta jalova nista imela nobenega otroka in oba sta bila zelo zvrhana v letih.',
        8: 'In pripetilo se je, medtem ko je pred Bogom opravljal duhovniško službo, po vrstnem redu svoje skupine,',
        9: 'glede na navado duhovniške službe, je bil na njem žreb, da zažge kadilo, ko je odšel v Gospodov tempelj.',
        10: 'Celotna množica ljudi pa je ob času zažiganja kadila zunaj molila.',
        11: 'In prikazal se mu je Gospodov angel, stoječ na desni strani kadilnega oltarja.',
        12: 'Ko pa ga je Zaharija zagledal, se je vznemiril in strah ga je spreletel.',
        13: 'Toda angel mu je rekel: »Ne boj se, Zaharija, kajti tvoja molitev je uslišana in tvoja žena Elizabeta ti bo rodila sina in ti boš klical njegovo ime Janez.',
        14: 'Imel boš radost in veselje in mnogi se bodo veselili ob njegovem rojstvu.',
        15: 'Kajti velik bo v Gospodovih očeh in ne bo pil niti vina niti močne pijače in celó od maternice svoje matere bo izpolnjen s Svetim Duhom.',
        16: 'In mnoge izmed Izraelovih otrok bo obrnil h Gospodu, njihovemu Bogu.',
        17: 'Pred njim bo šel z Elijevim duhom in močjo, da obrne srca očetov k otrokom in neposlušne k modrosti pravičnih; da pripravi ljudstvo, pripravljeno za Gospoda.«',
        18: 'Zaharija je angelu rekel: »Po čem bom to spoznal? Kajti starec sem in moja žena je zelo zvrhana v letih.«',
        19: 'Angel mu odgovori in reče: »Jaz sem Gabriel, ki stojim v prisotnosti Boga in poslan sem, da ti govorim in da ti pokažem te vesele novice.',
        20: 'Glej, ker nisi verjel mojim besedam, ki se bodo uresničile ob njihovem pravem času, boš postal nem in ne boš mogel govoriti do dne, ko se bodo te besede izpolnile.«',
        21: 'In ljudje so čakali na Zaharija in se čudili, da se je tako dolgo mudil v templju.',
        22: 'Ko pa je prišel ven, jim ni mogel spregovoriti, in zaznali so, da je videl v templju videnje, kajti dajal jim je znamenja, ostal pa je brez besed.',
        23: 'Pripetilo se je, kakor hitro so bili dnevi njegovega služenja dovršeni, da se je odpravil k svoji lastni hiši.',
        24: 'Po teh dneh je njegova žena Elizabeta spočela in se pet mesecev skrivala, rekoč:',
        25: '»Tako je Gospod ravnal z menoj v dneh, v katerih je pogledal name, da odvzame mojo grajo izmed ljudi.«',
        26: 'V šestem mesecu pa je bil od Boga poslan angel Gabriel v galilejsko mesto, imenovano Nazaret,',
        27: 'k devici, zaročeni z možem, katerega ime je bilo Jožef, iz Davidove hiše; in devici je bilo ime Marija.',
        28: '§ Angel je vstopil k njej in rekel: »Pozdravljena, ti, ki si zelo spoštovana, Gospod je s teboj, blagoslovljena si med ženskami.«',
        29: 'Ko pa ga je zagledala, je bila ob njegovem govoru zaskrbljena in v svojih mislih preudarjala, kakšne vrste pozdrav naj bi to bil.',
        30: 'Angel ji je rekel: »Ne boj se, Marija, kajti pri Bogu si našla naklonjenost.',
        31: 'Glej, v svoji maternici boš spočela in rodila sina in njegovo ime boš klicala JEZUS.',
        32: 'Velik bo in imenovan bo Sin Najvišjega; in Gospod Bog mu bo dal prestol njegovega očeta Davida',
        33: 'in nad Jakobovo hišo bo vladal večno in njegovemu kraljestvu ne bo konca.«',
        34: 'Potem je Marija rekla angelu: »Kako se bo to zgodilo, glede na to, da ne poznam moškega?«',
        35: 'Angel je odgovoril in ji rekel: »Sveti Duh bo prišel nadte in moč Najvišjega te bo obsenčila, zato bo tudi ta sveta oseba, ki bo rojena od tebe, imenovana Božji Sin.',
        36: 'Glej, tvoja sestrična Elizabeta je prav tako v svoji visoki starosti spočela sina, in to je šesti mesec z njo, ki je bila imenovana jalova.',
        37: 'Kajti z Bogom nič ne bo nemogoče.«',
        38: 'Marija je rekla: »Glej, Gospodova pomočnica; naj se mi zgodi glede na tvojo besedo.« In angel je odšel od nje.',
        39: 'Marija je v tistih dneh vstala in z naglico odšla v hribovito deželo, v Judovo mesto',
        40: 'in vstopila v Zaharijevo hišo ter pozdravila Elizabeto.',
        41: 'In pripetilo se je, ko je Elizabeta zaslišala Marijin pozdrav, da je dete poskočilo v njeni maternici in Elizabeta je bila izpolnjena s Svetim Duhom',
        42: 'in zaklicala z močnim glasom ter rekla: »Blagoslovljena si ti med ženskami in blagoslovljen je sad tvoje maternice.',
        43: 'Od kod je meni to, da bi prišla k meni mati mojega Gospoda?',
        44: 'Kajti glej, brž ko je glas tvojega pozdrava zazvenel v mojih ušesih, je dete v moji maternici od radosti poskočilo.',
        45: 'Blagoslovljena je tista, ki je verovala, kajti izpolnile se bodo te besede, ki so ji bile povedane od Gospoda.«',
        46: 'Marija je rekla: »Moja duša poveličuje Gospoda',
        47: 'in moj duh se veseli v Bogu, mojem Odrešeniku.',
        48: 'Kajti ozrl se je na nizek stan svoje pomočnice, kajti glej, odslej me bodo vsi rodovi imenovali blagoslovljeno.',
        49: 'Kajti tisti, ki je mogočen, mi je storil velike stvari in sveto je njegovo ime.',
        50: 'In njegovo usmiljenje je od roda do roda nad tistimi, ki se ga bojijo.',
        51: 'S svojim laktom je pokazal moč, ponosne je razgnal v domišljiji njihovih src.',
        52: 'Mogočne je odstranil z njihovih prestolov in povišal te z nizkim položajem.',
        53: 'Lačne je napolnil z dobrinami, bogate pa je odpustil prazne.',
        54: 'Pomagal je svojemu služabniku Izraelu, v spomin na svoje usmiljenje,',
        55: 'kakor je govoril našim očetom, Abrahamu in njegovemu semenu na veke.«',
        56: 'Marija je z njo ostala približno tri mesece in se vrnila v svojo lastno hišo.',
        57: 'Torej prišel je Elizabetin polni čas, ko naj bi rodila; in rodila je sina.',
        58: 'Njeni sosedje in njeni sorodniki so slišali, kako je Gospod nad njo izkazal veliko usmiljenje in veselili so se z njo.',
        59: 'Pripetilo pa se je, da so na osmi dan prišli, da obrežejo otroka in poimenovali so ga Zaharija, po imenu njegovega očeta.',
        60: 'Njegova mati pa je odgovorila in rekla: »Ne tako, temveč se bo imenoval Janez.«',
        61: 'Oni pa so ji rekli: »Nikogar v tvojem sorodstvu ni, ki je poimenovan s tem imenom.«',
        62: 'In naredili so znamenja njegovemu očetu, kako bi ga on imenoval.',
        63: 'In prosil je za pisalno deščico ter napisal, rekoč: »Njegovo ime je Janez.« In vsi so se čudili.',
        64: 'In njegova usta so se takoj odprla in njegov jezik se je sprostil in spregovoril je ter hvalil Boga.',
        65: 'In strah je prišel na vse, ki so prebivali naokoli njih; in vse te besede so se razglasile naokoli po vsej judejski hriboviti deželi.',
        66: 'In vsi, ki so jih slišali, so si jih položili v svoja srca, rekoč: »Kakšne vrste otrok bo to!« In Gospodova roka je bila z njim.',
        67: 'In njegov oče Zaharija je bil izpolnjen s Svetim Duhom in prerokoval, rekoč:',
        68: '»Blagoslovljen bodi Gospod, Izraelov Bog; kajti obiskal je in odkupil svoje ljudi',
        69: 'in za nas je dvignil rog rešitve duš v hiši svojega služabnika Davida,',
        70: 'kakor je govoril po ustih svojih svetih prerokov, ki so bili, odkar je svet nastal,',
        71: 'da bi bili mi lahko rešeni pred našimi sovražniki in iz roke vseh, ki nas sovražijo,',
        72: 'da opravi usmiljenje, obljubljeno našim očetom in se spomni svoje svete zaveze,',
        73: 'prisege, s katero je prisegel našemu očetu Abrahamu,',
        74: 'da nam bo zagotovil, da mu bomo osvobojeni iz roke svojih sovražnikov, lahko služili brez strahu,',
        75: 'v svetosti in pravičnosti pred njim, vse dni našega življenja.',
        76: 'Ti pa, otrok, boš imenovan prerok Najvišjega, kajti šel boš pred Gospodov obraz, da pripraviš njegove poti,',
        77: 'da daš njegovim ljudem spoznanje o rešitvi duš z odpuščanjem njihovih grehov,',
        78: 'po nežnem usmiljenju našega Boga; po katerem nas je obiskalo svitanje od zgoraj,',
        79: 'da da svetlobo tem, ki sedijo v temi in v smrtni senci, da vodi naša stopala na pot miru.«',
        80: 'Otrok pa je rasel in se krepil v duhu in bil je v puščavah do dneva njegove pojavitve Izraelu.',
    },
    2: {
        1: '§ In pripetilo se je v tistih dneh, da je od cesarja Avgusta izšel odlok, naj se obdavči ves svet.',
        2: '§ (In to obdavčenje je bilo prvič narejeno, ko je bil Kvirinij voditelj Sirije.)',
        3: '§ In vsi so odšli, da bi se obdavčili, vsakdo v svoje lastno mesto.',
        4: 'In tudi Jožef je odšel iz Galileje, iz mesta Nazaret, gor v Judejo, v Davidovo mesto, ki se imenuje Betlehem, (ker je bil iz Davidove hiše in rodovine)',
        5: '§ da bi bil obdavčen z Marijo, svojo zaročeno ženo, ki je bila noseča.',
        6: 'In bilo je tako, medtem ko sta bila tam, da so se ji dovršili dnevi, ko naj bi rodila.',
        7: 'In rodila je svojega prvorojenega sina ter ga zavila v plenice in ga položila v jasli, kajti v gostišču zanje ni bilo prostora.',
        8: 'In v isti deželi so bili pastirji, ki so se zadrževali na polju in so ponoči stražili nad svojim tropom.',
        9: 'In glej, Gospodov angel je prišel nadnje in Gospodova slava je zasijala naokoli njih in bili so boleče prestrašeni.',
        10: 'Angel pa jim je rekel: »Ne bojte se, kajti glejte, prinašam vam dobre novice o veliki radosti, ki bo za vse ljudi.',
        11: 'Kajti ta dan se vam je v Davidovem mestu rodil Odrešenik, ki je Kristus Gospod.',
        12: 'In to vam bo znamenje: ›Našli boste dojenčka, zavitega v plenice, ležečega v jaslih.‹«',
        13: 'In nenadoma je bila pri angelu množica nebeške vojske, ki je slavila Boga in govorila:',
        14: '§ »Slava Bogu na višavah in na zemlji mir, dobro voljo napram ljudem.«',
        15: 'In pripetilo se je, ko so angeli odšli proč od njih v nebesa, da so pastirji drug drugemu rekli: »Pojdimo sedaj celó v Betlehem in poglejmo to reč, ki se je pripetila, ki nam jo je dal spoznati Gospod.«',
        16: 'Prišli so v naglici ter našli Marijo in Jožefa ter dojenčka, ležečega v jaslih.',
        17: 'In ko so to videli, so povsod razglasili govor, ki jim je bil povedan glede tega otroka.',
        18: 'In vsi, ki so to slišali, so se čudili ob teh besedah, ki so jim jih povedali pastirji.',
        19: 'Toda Marija je vse te besede ohranila in jih preudarjala v svojem srcu.',
        20: 'In pastirji so se vrnili, slavili in hvalili Boga za vse stvari, ki so jih slišali in videli, tako, kakor jim je bilo povedano.',
        21: 'In ko je bilo dovršenih osem dni za otrokovo obrezovanje, je bilo njegovo ime imenovano JEZUS, tako, kakor je bil poimenovan po angelu, preden je bil spočet v maternici.',
        22: 'In ko so se dovršili dnevi njenega očiščevanja, glede na Mojzesovo postavo, so ga prinesli v Jeruzalem, da ga darujejo Gospodu,',
        23: '(kakor je pisano v Gospodovi postavi: ›Vsak moški, ki odpre maternico, bo imenovan svet Gospodu;‹)',
        24: 'in da darujejo žrtvovanje glede na to, kar je rečeno v Gospodovi postavi: ›Par grlic ali dva mlada goloba.‹',
        25: 'In glej, v Jeruzalemu je bil mož, katerega ime je bilo Simeon; in isti mož je bil pravičen ter predan, [in je] pričakoval Izraelovo tolažbo in Sveti Duh je bil nad njim.',
        26: 'In po Svetem Duhu mu je bilo razodeto, da naj ne bi videl smrti, dokler ne bo videl Gospodovega Kristusa.',
        27: 'In po Duhu je prišel v tempelj, in ko so starši prinesli otroka Jezusa, da bi zanj storili po običaju postave,',
        28: 'ga je nató vzel v svoje naročje in blagoslovil Boga ter rekel:',
        29: '»Gospod, sedaj odpuščaš svojega služabnika umreti v miru, glede na svojo besedo,',
        30: 'kajti moje oči so videle tvojo rešitev duš,',
        31: 'ki si jo pripravil pred obličjem vseh ljudi;',
        32: 'svetlobo, da razsvetli pogane in slavo tvojega ljudstva Izraela.«',
        33: '§ In Jožef in njegova mati sta se čudila ob vseh teh besedah, ki so se govorile o njem.',
        34: 'In Simeon jih je blagoslovil in rekel Mariji, njegovi materi: »Glej, ta otrok je v Izraelu postavljen za padec in ponovno vstajenje mnogih in za znamenje, ki se mu bo ugovarjalo,',
        35: '(da, meč bo presunil tudi tvojo lastno dušo), da se bodo lahko razodele misli mnogih src.«',
        36: 'In tam je bila neka Ana, prerokinja, Fanuélova hči, iz Aserjevega rodu. Bila je visoke starosti in od svojega devištva je sedem let preživela s soprogom',
        37: 'in bila je vdova, stara okoli štiriinosemdeset let, ki ni odhajala iz templja, temveč je noč in dan s posti in molitvami služila Bogu.',
        38: 'In ko je vstopila, je tisto uro na isti način dala zahvalo Gospodu in o njem spregovorila vsem, ki so v Jeruzalemu pričakovali odkupitev.',
        39: 'In ko so opravili vse stvari, glede na Gospodovo postavo, so se vrnili v Galilejo, v svoje lastno mesto Nazaret.',
        40: '§ In otrok je rasel in se krepil v duhu, napolnjen z modrostjo in Božja milost je bila nad njim.',
        41: 'Njegovi starši so torej ob prazniku pashe vsako leto hodili v Jeruzalem.',
        42: 'In ko je bil star dvanajst let, so po praznični navadi odšli gor v Jeruzalem.',
        43: '§ In ko so dovršili dneve, medtem ko so se vračali, je otrok Jezus ostal zadaj v Jeruzalemu; Jožef in njegova mati pa nista nič vedela o tem.',
        44: 'Toda onadva, ker sta mislila, da je v skupini, sta šla pot enega dne in ga iskala med svojo žlahto in znanci.',
        45: 'In ko ga nista našla, sta se, iščoč ga, ponovno obrnila nazaj v Jeruzalem.',
        46: 'In pripetilo se je, da sta ga po treh dneh našla v templju, sedečega v sredi med učenimi možmi in on jih je tako poslušal kakor jim zastavljal vprašanja.',
        47: 'In vsi, ki so ga slišali, so bili osupli nad njegovim razumevanjem in odgovori.',
        48: 'In ko sta ga zagledala, sta bila osupla in njegova mati mu je rekla: »Sin, zakaj si tako ravnal z nama? Glej, tvoj oče in jaz sva te zaskrbljena iskala.«',
        49: 'Rekel jima je: »Kako to, da sta me iskala? Mar nista vedela, da moram biti pri opravilu svojega Očeta?«',
        50: 'Onadva pa nista razumela besed, ki jima jih je govoril.',
        51: 'In z njima je odšel dol in prišel v Nazaret ter jima bil pokoren, toda njegova mati je vse te besede ohranila v svojem srcu.',
        52: 'Jezus pa je rasel v modrosti in postavi in naklonjenosti pri Bogu in ljudeh.',
    },
    3: {
        1: 'Torej v petnajstem letu vladanja cesarja Tiberija, ko je bil Poncij Pilat voditelj Judeje in Herod vladar četrtinskega dela province Galileje in njegov brat Filip vladar četrtinskega dela province Itureje in področja Trahonítide ter Lizanija vladar četrtinskega dela province Abilene,',
        2: 'Hana in Kajfa pa vélika duhovnika, je v divjini prišla Božja beseda k Janezu, Zaharijevemu sinu.',
        3: 'In ta je prišel v vso deželo okoli Jordana ter pridigal krst kesanja v odpuščanje grehov,',
        4: 'kakor je pisano v knjigi besed preroka Izaija, rekoč: »Glas nekoga vpijočega v divjini: ›Pripravite Gospodovo pot, izravnajte njegove steze.',
        5: 'Vsaka dolina naj bo napolnjena in vsaka gora in hrib naj bosta znižana in skrivljeno naj bo izravnano in neravne poti naj bodo izglajene',
        6: 'in vse meso bo videlo Božjo rešitev duš.‹«',
        7: 'Potem je rekel množici, ki je prihajala, da bi jih krstil: »Oh gadji rod, kdo vas je opozoril, da pobegnete pred besom, ki pride?',
        8: 'Obrodite torej sadove, vredne kesanja in ne začnite v sebi govoriti: ›Abrahama imamo za svojega očeta,‹ kajti povem vam: ›Da je Bog iz teh kamnov zmožen Abrahamu obuditi otroke.‹',
        9: 'In sedaj je prav tako sekira nastavljena drevesom na korenino; vsako drevo, ki torej ne prinaša dobrega sadu, je posekano in vrženo v ogenj.«',
        10: 'In množica ga je spraševala, rekoč: »Kaj naj potem storimo?«',
        11: 'Odgovarja in jim reče: »Kdor ima dva plašča, naj da tistemu, ki nima nobenega; in kdor ima hrano, naj stori enako.«',
        12: 'Potem so prišli tudi davkarji, da bi bili krščeni in mu rekli: »Učitelj, kaj naj storimo?«',
        13: 'Rekel jim je: »Ne terjajte nič več kakor to, kar vam je določeno.«',
        14: 'In prav tako so od njega zahtevali vojaki, rekoč: »In kaj naj mi storimo?« In rekel jim je: »Nobenemu človeku ne storite nasilja niti nikogar po krivem ne obdolžite in zadovoljni bodite s svojimi plačami.«',
        15: 'In medtem ko so bili ljudje v pričakovanju in so vsi ljudje v svojih srcih razglabljali o Janezu, če je bil on Kristus ali ne,',
        16: 'je Janez odgovoril, rekoč njim vsem: »Zares, jaz vas krščujem z vodo, toda prihaja nekdo mogočnejši od mene, čigar čevljev jermena nisem vreden odvezati. On vas bo krstil s Svetim Duhom in z ognjem;',
        17: 'katerega vejálnik je v njegovi roki in svoje mlatišče bo temeljito očistil in pšenico bo spravil v svojo kaščo, toda pleve bo sežgal z nepogasljivim ognjem.«',
        18: '§ In mnoge druge besede je v svojem spodbujanju oznanjal ljudem.',
        19: 'Toda Herod, vladar četrtinskega dela province, od njega pograjan zaradi Herodiade, žene njegovega brata Filipa in zaradi vseh hudobij, ki jih je storil Herod,',
        20: 'je povrh vsega dodal še to, da je Janeza zaprl v ječo.',
        21: 'Ko so bili torej vsi ljudje krščeni, se je pripetilo, da je bil krščen tudi Jezus, in ko je molil, se je odprlo nebo',
        22: 'in Sveti Duh se je spustil nadenj v telesni obliki, podoben golobici in glas je prišel z neba, ki je rekel: »Ti si moj ljubljeni Sin; s teboj sem zelo zadovoljen.«',
        23: 'In sam Jezus je šel v trideseto leto starosti, in (kakor se je domnevalo) je bil sin Jožefa, ki je bil Élijev sin,',
        24: 'ki je bil Matátov sin, ki je bil Lévijev sin, ki je bil Melhíjev sin, ki je bil Janájev sin, ki je bil Jožefov sin,',
        25: 'ki je bil Matitjájev sin, ki je bil Amosov sin, ki je bil Nahumov sin, ki je bil Heslíjev sin, ki je bil Nangájev sin,',
        26: 'ki je bil Mahatov sin, ki je bil Matitjájev sin, ki je bil Šimíjev sin, ki je bil Jozéhov sin, ki je bil Jodájev sin,',
        27: 'ki je bil Johanánov sin, ki je bil Rezájev sin, ki je bil Zerubabélov sin, ki je bil Šaltiélov sin, ki je bil Neríjev sin,',
        28: 'ki je bil Melhíjev sin, ki je bil Adíjev sin, ki je bil Kosámov sin, ki je bil Elmadámov sin, ki je bil Erov sin,',
        29: 'ki je bil Jošúov sin, ki je bil Eliézerjev sin, ki je bil Jorímov sin, ki je bil Matátov sin, ki je bil Lévijev sin,',
        30: 'ki je bil Simeonov sin, ki je bil Judov sin, ki je bil Jožefov sin, ki je bil Jonámov sin, ki je bil Eljakímov sin,',
        31: 'ki je bil Meleájev sin, ki je bil Menájev sin, ki je bil Matatájev sin, ki je bil Natánov sin, ki je bil Davidov sin,',
        32: 'ki je bil Jesejev sin, ki je bil Obédov sin, ki je bil Boazov sin, ki je bil Salmónov sin, ki je bil Nahšónov sin,',
        33: '§ ki je bil Aminadábov sin, ki je bil Aramov sin, ki je bil Hecrónov sin, ki je bil Perecov sin, ki je bil Judov sin,',
        34: 'ki je bil Jakobov sin, ki je bil Izakov sin, ki je bil Abrahamov sin, ki je bil Terahov sin, ki je bil Nahórjev sin,',
        35: 'ki je bil Serúgov sin, ki je bil Regujev sin, ki je bil Pelegov sin, ki je bil Eberjev sin, ki je bil Šelahov sin,',
        36: 'ki je bil Kenánov sin, ki je bil Arpahšádov sin, ki je bil Semov sin, ki je bil Noetov sin, ki je bil Lamehov sin,',
        37: 'ki je bil Matuzalemov sin, ki je bil Henohov sin, ki je bil Jeredov sin, ki je bil Mahalalélov sin, ki je bil Kenánov sin,',
        38: 'ki je bil Enóšev sin, ki je bil Setov sin, ki je bil Adamov sin, ki je bil Božji sin.',
    },
    4: {
        1: 'In Jezus se je poln Svetega Duha vrnil od Jordana in po Duhu je bil voden v divjino',
        2: 'in štirideset dni je bil skušan od hudiča. In v tistih dneh ni ničesar jedel, in ko so se končali, je bil potem lačen.',
        3: 'In hudič mu je rekel: »Če si Božji Sin, ukaži temu kamnu, da naj postane kruh.«',
        4: '§ In Jezus mu je odgovoril, rekoč: »Pisano je: ›Da človek ne bo živel samo od kruha, temveč od vsake Božje besede.‹«',
        5: 'In hudič, ki ga je vzel gor na visoko goro, mu je v trenutku časa pokazal vsa kraljestva sveta.',
        6: 'In hudič mu je rekel: »Vso to oblast hočem predati tebi in njihovo slavo, kajti ta mi je izročena in dam jo komurkoli hočem.',
        7: 'Če me torej hočeš oboževati, bo vsa tvoja.«',
        8: '§ Jezus pa je odgovoril in mu rekel: »Spravi se za menoj, Satan, kajti pisano je: ›Gospoda, svojega Boga, obožuj in njemu samemu služi.‹«',
        9: 'In odvedel ga je v Jeruzalem in ga postavil na vrh templja ter mu rekel: »Če si Božji Sin, se vrzi od tod dol,',
        10: 'kajti pisano je: ›Svojim angelom bo zate naročil, da te varujejo',
        11: 'in na svojih rokah te bodo prenašali, da ne bi kadarkoli s svojo nogo treščil ob kamen.‹«',
        12: 'Jezus pa mu odgovori in reče: »Rečeno je: ›Ne boš skušal Gospoda, svojega Boga.‹«',
        13: 'In ko je hudič končal vse skušnjave, je za nekaj časa odšel od njega.',
        14: 'In Jezus se je v moči Duha vrnil v Galilejo in tam je šel slôves o njem naokoli po vsem področju.',
        15: 'In učil je v njihovih sinagogah in od vseh je bil proslavljen.',
        16: 'In prišel je v Nazaret, kjer je bil vzgojen in kakor je bila njegova navada, je na šabatni dan odšel v sinagogo in vstal, da bi bral.',
        17: 'In izročena mu je bila knjiga preroka Izaija. In ko je odprl knjigo, je našel mesto, kjer je bilo zapisano:',
        18: '»Gospodov Duh je nad menoj, ker me je mazilil, da oznanim evangelij revnim. Poslal me je, da ozdravim zlomljene v srcu, da oznanim jetnikom osvoboditev in slepim okrevanje vida, da izpustim na prostost te, ki so ranjeni,',
        19: 'da oznanim sprejemljivo leto Gospodovo.«',
        20: 'In zaprl je knjigo in jo dal nazaj služitelju ter se usedel. In oči vseh, ki so bili v sinagogi, so bile uprte vanj.',
        21: 'In začel jim je govoriti: »Ta dan se je to pismo izpolnilo v vaših ušesih.«',
        22: 'In vsi so očitno pričevali zanj ter se čudili ob milostnih besedah, ki so izvirale iz njegovih ust. In rekli so: »Ali ni to Jožefov sin?«',
        23: 'Rekel jim je: »Zagotovo mi boste povedali ta pregovor: ›Zdravnik, ozdravi sebe.‹ Karkoli smo slišali, da je bilo storjeno v Kafarnáumu, prav tako stôri tukaj, v svoji deželi.«',
        24: 'In rekel je: »Resnično, povem vam: ›Noben prerok ni sprejet v svoji lastni deželi.‹',
        25: 'Toda povem vam po resnici, mnogo vdov je bilo v Izraelu v Elijevih dneh, ko je bilo nebo zaprto tri leta in šest mesecev, ko je bila velika lakota po vsej celotni deželi,',
        26: 'toda k nobeni izmed njih ni bil poslan Elija, razen v Sarepto, mesto na Sidónskem, k ženski, ki je bila vdova.',
        27: 'In v času preroka Elizeja je bilo v Izraelu mnogo gobavcev. In nobeden izmed njih ni bil očiščen, razen Sirca Naamána.«',
        28: 'In ko so vsi ti v sinagogi slišali te besede, so bili izpolnjeni z besom',
        29: 'in vstali so in ga pahnili iz mesta in ga odvedli na skalno strmino hriba, na katerem je bilo zgrajeno njihovo mesto, da bi ga lahko z glavo naprej vrgli dol.',
        30: 'Toda šel je skozi njihovo sredo in odšel svojo pot',
        31: 'in prišel dol v Kafarnáum, mesto v Galileji ter jih na šabatne dneve učil.',
        32: 'In nad njegovim naukom so bili osupli, kajti njegova beseda je bila z oblastjo.',
        33: 'In v sinagogi je bil človek, ki je imel duha nečistega hudiča in z močnim glasom je zakričal,',
        34: 'rekoč: »Pusti nas pri miru, kaj imamo s teboj, ti Jezus Nazarečan? Si prišel, da nas uničiš? Poznam te, kdo si; Sveti od Boga.«',
        35: 'Jezus pa ga je oštel, rekoč: »Umolkni in pridi ven iz njega.« In ko ga je hudič vrgel na sredo, je prišel iz njega in ga ni poškodoval.',
        36: 'In vsi so bili osupli in med seboj so govorili, rekoč: »Kakšna beseda je to! Kajti z oblastjo in močjo ukazuje nečistim duhovom in ti pridejo ven.«',
        37: 'In njegov slôves je šel naokoli v vsak kraj te dežele.',
        38: 'In vstal je iz sinagoge ter vstopil v Simonovo hišo. Simonova tašča pa je bila prevzeta z veliko vročico in oni so ga zaradi nje rotili.',
        39: 'In stopil je nad njo in oštel vročico in ta jo je zapustila in takoj je vstala ter jim služila.',
        40: 'Torej ko je sonce zahajalo, so vsi, ki so imeli kogarkoli bolnega z raznimi boleznimi, te pripeljali k njemu in na vsakogar izmed njih je položil svoji roki ter jih ozdravil.',
        41: 'In tudi hudiči so izhajali iz mnogih, kričali in govorili: »Ti si Kristus, Božji Sin.« In ko jih je ukoril, jim ni dovolil govoriti, kajti vedeli so, da je bil on Kristus.',
        42: 'In ko je bil dan, se je odpravil in odšel na zapuščen kraj in množica ga je iskala in prišla k njemu in ga zadržala, da ne bi odšel od njih.',
        43: 'Rekel jim je: »Tudi drugim mestom moram oznaniti Božje kraljestvo, kajti zato sem poslan.«',
        44: 'In oznanjal je po galilejskih sinagogah.',
    },
    5: {
        1: 'In pripetilo se je, medtem ko je množica pritiskala nanj, da sliši Božjo besedo, [da] je stal ob Genezareškem jezeru',
        2: 'in zagledal dve ladji, pripravljeni pri jezeru, toda ribiči so odšli iz njiju ter izpirali svoje mreže.',
        3: 'In vstopil je v eno izmed ladij, ki je bila Simonova in ga prosil, da bi odrinil malce proč od kopnega. In usedel se je ter iz ladje učil množico.',
        4: '§ Torej, ko je prenehal govoriti, je rekel Simonu: »Kreni na globoko in spusti dol svoje mreže za vleko.«',
        5: 'Simon pa mu odgovori in reče: »Učitelj, celó noč smo garali, pa nismo nič ujeli. Vendar bom na tvojo besedo to mrežo spustil dol.«',
        6: 'In ko so to storili, so zajeli veliko množino rib in njihova mreža se je pretrgala.',
        7: 'In dali so znamenje svojim družabnikom, ki so bili na drugi ladji, da naj pridejo ter jim pomagajo. In prišli so ter napolnili obe ladji, tako da sta se začeli potapljati.',
        8: 'Ko je Simon Peter to videl, je pri Jezusovih kolenih padel dol, rekoč: »Odidi od mene, oh Gospod, kajti grešen človek sem.«',
        9: 'Kajti nad ulovom rib, ki so jih zajeli, je bil osupel on in vsi ti, ki so bili z njim;',
        10: 'in tako sta bila tudi Jakob in Janez, Zebedejeva sinova, ki sta bila Simonova družabnika. In Jezus je Simonu rekel: »Ne boj se, odslej boš lovil ljudi.«',
        11: 'In ko so svoji ladji pripeljali do kopnega, so vse zapustili in mu sledili.',
        12: 'In pripetilo se je, ko je bil v nekem mestu, [da] zagleda človeka polnega gobavosti. Ko je [le-ta] zagledal Jezusa, je padel na svoj obraz ter ga rotil, rekoč: »Gospod, če hočeš, me lahko očistiš.«',
        13: 'In iztegnil je svojo roko ter se ga dotaknil, rekoč: »Hočem, bodi čist.« In gobavost je takoj odšla od njega.',
        14: 'In naročil mu je, da ne pove nobenemu človeku: »Temveč pojdi in se pokaži duhovniku ter daruj za svoje očiščenje glede na Mojzesovo zapoved, njim v pričevanje.«',
        15: 'Toda beseda o njem je toliko bolj na veliko šla naokoli in velike množice so prišle skupaj, da poslušajo in da bi bile po njem ozdravljene svojih slabotnosti.',
        16: 'On pa se je umaknil v divjino in molil.',
        17: 'In pripetilo se je na določeni dan, medtem ko je učil, da so bili tam, sedeči poleg, farizeji in učeni možje postave, ki so prišli iz vsakega mesta Galileje, Judeje in Jeruzalema. In Gospodova moč je bila prisotna, da jih ozdravi.',
        18: 'In glej, možje so prinesli na postelji človeka, ki je bil prevzet s paralizo in iskali so načine, da ga prinesejo noter in da ga položijo predenj.',
        19: 'Ko pa zaradi množice niso mogli najti, po kateri poti bi ga lahko prinesli noter, so odšli na hišno streho in ga z njegovim ležiščem vred spustili navzdol skozi strešno kritino v sredo pred Jezusa.',
        20: 'In ko je videl njihovo vero, mu je rekel: »Človek, tvoji grehi so ti odpuščeni.«',
        21: 'In pisarji in farizeji so začeli premišljevati, rekoč: »Kdo je ta, ki govori bogokletja? Kdo lahko odpušča grehe razen samo Bog?«',
        22: 'Toda ko je Jezus zaznal njihove misli, jim je odgovoril in rekel: »Kaj razmišljate v svojih srcih?',
        23: 'Ali je lažje reči: ›Tvoji grehi naj ti bodo odpuščeni‹ ali reči: ›Dvigni se in hôdi?‹',
        24: 'Toda da boste lahko vedeli, da ima Sin človekov na zemlji oblast odpuščati grehe,« (je rekel bolnemu zaradi paralize) »jaz ti pravim: ›Vstani in vzemi svoje ležišče in pojdi v svojo hišo.‹«',
        25: 'In ta je pred njimi takoj vstal ter pobral to, na čemer je ležal in odšel k svoji lastni hiši, proslavljajoč Boga.',
        26: 'In vsi so bili osupli in slavili Boga in izpolnjeni so bili s strahom, rekoč: »Danes smo videli čudne stvari.«',
        27: 'Po teh stvareh pa je odšel dalje in zagledal davkarja, imenovanega Levi, ki je sedel pri kraju plačevanja davkov in mu rekel: »Sledi mi.«',
        28: 'In ta je pustil vse, vstal ter mu sledil.',
        29: 'In Levi mu je v svoji lastni hiši pripravil veliko praznovanje; in bila je velika skupina davkarjev in drugih, ki so se z njimi usedli.',
        30: 'Toda njihovi pisarji in farizeji so godrnjali zoper njegove učence, rekoč: »Zakaj jeste in pijete z davkarji in grešniki?«',
        31: 'In Jezus jim odgovori ter reče: »Tisti, ki so zdravi, ne potrebujejo zdravnika, temveč tisti, ki so bolni.',
        32: 'Nisem prišel klicat pravičnih, temveč grešnike h kesanju.«',
        33: 'In rekli so mu: »Zakaj se Janezovi učenci pogosto postijo in opravljajo molitve in enako učenci farizejev, tvoji pa jedo in pijejo?«',
        34: 'Rekel jim je: »Ali lahko primorate otroke svatovske sobe, da se postijo, medtem ko je z njimi ženin?',
        35: 'Toda prišli bodo dnevi, ko bo ženin odvzet od njih in tedaj, v tistih dneh, se bodo postili.«',
        36: 'In povedal jim je tudi prispodobo: »Nihče ne polaga koščka iz nove obleke na staro; če drugače, potem nov dela raztrganino in tudi košček, ki je bil odvzet iz nove, se ne ujema s staro.',
        37: 'In novega vina nihče ne vliva v stare mehove, sicer bo novo vino mehove razgnalo in bo izlito in mehovi bodo propadli.',
        38: '§ Toda novo vino mora biti vlito v nove mehove in oboje je ohranjeno.',
        39: 'Prav tako nihče, ki je pil staro vino, noče nemudoma novega, kajti pravi: ›Staro je boljše.‹«',
    },
    6: {
        1: 'In pripetilo se je na drugi šabat za prvim, da je šel skozi žitna polja in njegovi učenci so smukali žitno klasje, ga méli v svojih rokah in jedli.',
        2: 'Nekateri izmed farizejev so jim rekli: »Zakaj delate to, kar ni zakonito delati na šabatne dneve?«',
        3: 'Jezus jim odgovori in reče: »Mar niste brali tega, kar je storil David, ko je bil lačen on sam in ti, ki so bili z njim;',
        4: 'kako je odšel v Božjo hišo in vzel in jedel hlebe navzočnosti in jih dal tudi tistim, ki so bili z njim; kar ni zakonito jésti [nikomur], razen samo duhovnikom?«',
        5: 'Rekel jim je: »Sin človekov je tudi Gospodar šabata.«',
        6: 'In prav tako se je na še en šabat pripetilo, da je vstopil v sinagogo ter učil, in tam je bil človek, čigar desna roka je bila izsušena.',
        7: 'In pisarji in farizeji so ga opazovali ali bo ozdravljal na šabatni dan, da bi zoper njega lahko našli obtožbo.',
        8: 'Toda poznal je njihove misli in rekel možu, ki je imel izsušeno roko: »Vstani in stopi na sredo.« In ta je vstal ter stopil naprej.',
        9: 'Potem jim je Jezus rekel: »Eno stvar vas bom vprašal: ›Ali je na šabatne dneve zakonito delati dobro ali delati zlo? Rešiti življenje ali ga uničiti?‹«',
        10: '§ In ko je pogledal naokoli po vseh, je rekel možu: »Iztegni svojo roko.« In ta je storil tako in njegova roka je bila v celoti ozdravljena, tako kakor druga.',
        11: 'In bili so izpolnjeni z besom in drug z drugim so se posvetovali, kaj bi lahko storili Jezusu.',
        12: 'In pripetilo se je v tistih dneh, da je odšel ven na goro, da moli in je vso noč vztrajal v molitvi k Bogu.',
        13: 'In ko je bil dan, je k sebi poklical svoje učence in izmed njih jih je izbral dvanajst, ki jih je imenoval tudi apostole:',
        14: 'Simona (ki ga je imenoval tudi Peter) in njegovega brata Andreja, Jakoba in Janeza, Filipa in Bartolomeja,',
        15: 'Mateja in Tomaža, Jakoba, Alfejevega sina in Simona, imenovanega Gorečnik,',
        16: 'in Juda, Jakobovega brata in Juda Iškarijota, ki je bil tudi izdajalec.',
        17: 'In z njimi je prišel dol ter stal na ravnem in skupina njegovih učencev ter velika množica ljudi iz vse Judeje in Jeruzalema in pokrajin Tira in Sidóna, ki so prišli, da ga poslušajo in da bi bili ozdravljeni svojih bolezni,',
        18: 'in tisti, ki so bili nadlegovani z nečistimi duhovi in bili so ozdravljeni.',
        19: 'In celotna množica si je prizadevala, da bi se ga dotaknila, kajti iz njega je izhajala moč in jih vse ozdravljala.',
        20: 'In povzdignil je svoje oči na svoje učence ter rekel: »Blagoslovljeni bodite vi ubogi, kajti vaše je Božje kraljestvo.',
        21: 'Blagoslovljeni ste vi, ki ste sedaj lačni, kajti nasičeni boste. Blagoslovljeni ste vi, ki sedaj jokate, kajti smejali se boste.',
        22: 'Blagoslovljeni ste, ko vas bodo ljudje sovražili in ko vas bodo oddvojili od svoje družbe in vas bodo grajali in zaradi Sina človekovega vaše ime zavrgli kot hudobno.',
        23: 'Veselite se na tisti dan in poskakujte od radosti, kajti, glejte, vaša nagrada v nebesih je velika, kajti na podoben način so njihovi očetje delali prerokom.',
        24: 'Toda gorje vam, ki ste bogati! Kajti prejeli ste svojo tolažbo.',
        25: 'Gorje vam, ki ste siti! Kajti lačni boste. Gorje vam, ki se sedaj smejete! Kajti žalovali boste in jokali.',
        26: 'Gorje vam, ko bodo vsi ljudje o vas lepo govorili! Kajti tako so njihovi očetje delali lažnim prerokom.',
        27: 'Toda jaz pravim vam, ki slišite: ›Ljubite svoje sovražnike, delajte dobro tem, ki vas sovražijo,',
        28: 'blagoslavljajte te, ki vas preklinjajo in molite za tiste, ki vas kruto izkoriščajo.',
        29: 'In tistemu, ki te udarja na eno lice, ponudi še drugo; in tistemu, ki odvzema tvoje ogrinjalo, ne prepovej vzeti tudi svojega plašča.',
        30: 'Vsakemu človeku daj, kar prosi od tebe in od tistega, ki jemlje tvoje dobrine, ne prosi ponovno zanje.',
        31: 'In kakor želite, da bi ljudje storili vam, prav tako tudi vi storite njim.',
        32: 'Kajti če ljubite te, ki ljubijo vas, kakšno hvalo imate? Kajti tudi grešniki ljubijo tiste, ki ljubijo njih.',
        33: 'In če delate dobro tem, ki delajo dobro vam, kakšno hvalo imate? Kajti tudi grešniki celó enako delajo.',
        34: 'In če posojate tistim, od katerih upate, da prejmete, kakšno hvalo imate? Kajti tudi grešniki posojajo grešnikom, da prejmejo toliko nazaj.',
        35: 'Toda ljubite svoje sovražnike in delajte dobro in posojajte ter se ničesar ne nadejajte v vrnitev in vaša nagrada bo velika in boste otroci Najvišjega, kajti on je prijazen do nehvaležnih in do hudobnih.',
        36: 'Bodite torej usmiljeni, kakor je tudi vaš Oče usmiljen.',
        37: 'Ne sodite in ne boste sojeni, ne obsojajte in ne boste obsojeni, odpuščajte in vam bo odpuščeno,',
        38: 'dajajte in to vam bo dano; dobro mero, potlačeno in skupaj zbrano in čez rob polno vam bodo ljudje dali v vaše naročje. Kajti z enako mero, s katero vi merite, bo tudi vam ponovno odmerjeno.‹',
        39: 'In spregovoril jim je prispodobo: ›Mar lahko slepi vodi slepega? Ali ne bosta oba padla v jarek?',
        40: 'Učenec ni nad svojim učiteljem, toda vsak, kdor je popoln, bo kakor njegov učitelj.',
        41: 'In zakaj gledaš drobec, ki je v očesu svojega brata, toda ne zaznavaš bruna, ki je v tvojem lastnem očesu?‹',
        42: 'Ali kako lahko rečeš svojemu bratu: ›Brat, dovoli mi izvleči drobec, ki je v tvojem očesu,‹ ko sam ne zapaziš bruna, ki je v tvojem lastnem očesu? Ti hinavec, vrzi ven najprej bruno iz svojega lastnega očesa in tedaj boš jasno videl izvleči drobec, ki je v očesu tvojega brata.',
        43: 'Kajti dobro drevo ne prinaša slabega sadu niti slabo drevo ne prinaša dobrega sadu.',
        44: 'Kajti vsako drevo je razpoznano po svojem lastnem sadu. Kajti ljudje fig ne nabirajo s trnja niti z robidovega grma ne nabirajo grozdja.',
        45: 'Dober človek iz dobrega zaklada svojega srca prinaša to, kar je dobro, hudobnež pa iz zlega zaklada svojega srca prinaša to, kar je zlo, kajti iz obilja srca njegova usta govoré.',
        46: 'In zakaj me kličete: ›Gospod, Gospod,‹ pa ne delate stvari, ki jih govorim?',
        47: 'Kdorkoli pride k meni in posluša moje besede ter jih izpolnjuje, vam bom pokazal, komu je podoben.',
        48: '§ Podoben je človeku, ki je gradil hišo in globoko kopál ter položil temelj na skalo. In ko je nastala poplava, je na to hišo silovito udaril vodni tok in je ni mogel omajati, kajti utemeljena je bila na skali.',
        49: 'Toda kdor posluša, pa ne dela, je podoben človeku, ki je na zemlji zgradil hišo brez temelja, proti kateri je silovito udaril vodni tok in ta je takoj padla in ruševina te hiše je bila velika.«',
    },
    7: {
        1: 'Ko je torej končal vse svoje govore pred občinstvom ljudi, je vstopil v Kafarnáum.',
        2: 'Neki služabnik stotnika, ki mu je bil dragocen, je bil bolan in pripravljen na smrt.',
        3: 'Ko je slišal o Jezusu, je k njemu poslal judovske starešine in ga rotil, da bi prišel in ozdravil njegovega služabnika.',
        4: 'Ko so prišli k Jezusu, so ga takoj iskreno rotili, rekoč: »Vreden je bil, da bi to storil zanj,',
        5: 'kajti rad ima naš narod in sinagogo nam je zgradil.«',
        6: 'Potem je Jezus odšel z njimi. In ko je bil torej nedaleč od hiše, je stotnik k njemu poslal prijatelje, rekoč mu: »Gospod, ne delaj si sitnosti, kajti nisem vreden, da bi stopil pod mojo streho,',
        7: 'zato se tudi nisem imel za vrednega, da bi prišel k tebi, toda reci besedo in moj služabnik bo ozdravljen.',
        8: 'Kajti tudi sam sem človek, postavljen pod oblast. Pod seboj imam vojake in nekomu rečem: ›Pojdi,‹ in gre, in drugemu: ›Pridi‹ in pride, in svojemu služabniku: ›Naredi to,‹ in to stori.«',
        9: 'Ko je Jezus slišal te besede, se je začudil nad njim in se obrnil ter rekel množici, ki mu je sledila: »Povem vam: ›Nisem našel tako velike vere, ne, niti v Izraelu ne.‹«',
        10: '§ In tisti, ki so bili poslani, so se vrnili k hiši in našli služabnika, ki je bil bolan, zdravega.',
        11: '§ Pripetilo se je dan kasneje, da je odšel v mesto, imenovano Nain in z njim so odšli mnogi izmed njegovih učencev ter veliko ljudi.',
        12: 'Ko je torej prišel blizu k mestnim velikim vratom, glej, je bil ven odnesen mrtev človek, edini sin njegove matere in ta je bila vdova; in z njo je bilo veliko ljudi iz mesta.',
        13: 'Ko jo je Gospod zagledal, je imel sočutje do nje in ji je rekel: »Ne jokaj.«',
        14: 'Prišel je in se dotaknil mrtvaškega odra, in tisti, ki so ga nosili, so mirno stali. In rekel je: »Mladenič, rečem ti: ›Vstani.‹«',
        15: 'In ta, ki je bil mrtev, se je usedel in začel govoriti. In izročil ga je njegovi materi.',
        16: 'Strah je prišel na vse in slavili so Boga, rekoč, da je med nami vstal velik prerok in da je Bog obiskal svoje ljudi.',
        17: 'In ta govorica o njem je šla naprej po vsej celotni Judeji in naokoli po vsem celotnem področju.',
        18: 'In Janezovi učenci so mu povedali o vseh teh stvareh.',
        19: '§ In Janez je k sebi poklical dva izmed svojih učencev in ju poslal k Jezusu, rekoč: »Ali si ti tisti, ki naj bi prišel? Ali [naj] pričakujemo drugega?«',
        20: 'Ko sta moža prišla k njemu, sta rekla: »Janez Krstnik naju je poslal k tebi, rekoč: ›Ali si ti tisti, ki naj bi prišel? Ali [naj] pričakujemo drugega?‹«',
        21: 'In v tej isti uri je mnoge ozdravil njihovih slabotnosti in nadlog ter od zlih duhov, in mnogim, ki so bili slepi, je dal vid.',
        22: 'Potem jima Jezus odgovori in reče: »Pojdita svojo pot in povejta Janezu, kakšne stvari sta videla in slišala: kako slepi vidijo, hromi hodijo, gobavi so očiščeni, gluhi slišijo, mrtvi so obujeni, revnim je oznanjen evangelij.',
        23: 'In blagoslovljen je, kdorkoli se ne bo spotaknil ob mene.«',
        24: 'In ko sta Janezova poslanca odšla, je množici začel govoriti glede Janeza: »Kaj ste odšli ven v divjino, da vidite? Trst, ki se maje z vetrom?',
        25: 'Toda kaj ste odšli ven, da vidite? Človeka, oblečenega v mehka oblačila? Glejte, tisti, ki so krasno oblečeni in žive prefinjeno, so na kraljevih dvorih.',
        26: 'Toda kaj ste odšli ven, da vidite? Preroka? Da, povem vam in veliko več kakor preroka.',
        27: 'To je on, o katerem je pisano: ›Glej, svojega poslanca pošljem pred tvoj obraz, ki bo pripravil tvojo pot pred teboj.‹',
        28: 'Kajti povem vam: ›Med temi, ki so rojeni iz žensk, ni večjega preroka kakor Janez Krstnik, toda kdor je v Božjem kraljestvu najmanjši, je večji od njega.‹«',
        29: 'In vsi ljudje, ki so ga slišali in davkarji, so resničnost Boga opravičili s tem, da so se krstili z Janezovim krstom.',
        30: 'Toda farizeji in izvedenci v postavi so zavrnili nasvet Boga, sami zoper sebe, tako da se mu niso dali krstiti.',
        31: '§ In Gospod je rekel: »S kom naj torej primerjam ljudi tega rodu? In čemú so podobni?',
        32: 'Podobni so otrokom, sedečim na trgu, ki kličejo drug drugemu ter govorijo: ›Piskali smo vam, pa niste plesali; objokovali smo vam, pa niste jokali.‹',
        33: 'Kajti Janez Krstnik je prišel [in] niti ni jedel kruha niti ni pil vina; vi pa pravite: ›Hudiča ima.‹',
        34: 'Sin človekov je prišel in jé ter pije; vi pa pravite: ›Glejte, požrešen človek in vinski bratec, prijatelj davkarjev in grešnikov!‹',
        35: 'Toda modrost je opravičena po vseh svojih otrocih.«',
        36: 'Eden izmed farizejev pa ga je prosil, da bi lahko jedel z njim. In odšel je v farizejevo hišo ter se usedel k obedu.',
        37: 'In glej, ko je ženska, ki je bila v mestu grešnica, spoznala, da je Jezus sedel v farizejevi hiši pri obedu, je prinesla alabastrno škatlo mazila',
        38: 'ter jokajoč od zadaj pristopila k njegovim stopalom in njegova stopala začela umivati s solzami in jih brisati z lasmi svoje glave in poljubljala je njegova stopala ter jih mazilila z mazilom.',
        39: 'Ko je torej to videl farizej, ki ga je povabil, si je rekel sam pri sebi, rekoč: »Če bi bil ta človek prerok, bi vedel, kdo in kakšne vrste je ta ženska, ki se ga dotika, kajti grešnica je.«',
        40: 'In Jezus mu odgovori ter reče: »Simon, nekaj ti imam povedati.« On pa reče: »Učitelj, povej.«',
        41: '»Bil je nek upnik, ki je imel dva dolžnika. Eden mu je bil dolžan petsto denarjev, drugi pa petdeset.',
        42: 'In ko nista imela nič, s čimer bi plačala, jima je obema odkrito odpustil. Povej mi torej, kateri izmed njiju ga bo bolj ljubil?«',
        43: 'Simon je odgovoril in rekel: »Domnevam, da tisti, ki mu je več odpustil.« On pa mu je rekel: »Pravilno si presodil.«',
        44: 'In obrnil se je k ženski ter rekel Simonu: »Vidiš to žensko? V tvojo hišo sem vstopil, pa mi nisi dal vode za moja stopala, toda ona je moja stopala umila s solzami in jih obrisala z lasmi svoje glave.',
        45: 'Nisi mi dal poljuba, toda odkar sem vstopil, ta ženska ni prenehala poljubljati mojih stopal.',
        46: 'Moje glave nisi mazilil z oljem, toda ta ženska je moja stopala mazilila z mazilom.',
        47: 'Zato ti pravim: ›Njeni grehi, ki jih je mnogo, so odpuščeni,‹ kajti veliko je ljubila, toda komur je malo oproščeno, ta malo ljubi.«',
        48: 'Njej pa je rekel: »Tvoji grehi so odpuščeni.«',
        49: 'In tisti, ki so pri obedu sedeli z njim, so v sebi začeli govoriti: »Kdo je ta, da tudi grehe odpušča?«',
        50: 'In ženski je rekel: »Tvoja vera te je rešila, pojdi v miru.«',
    },
    8: {
        1: 'In pripetilo se je potem, da je šel skozi vsako mesto in vas in oznanjal ter prikazoval vesele novice Božjega kraljestva in z njim so bili dvanajsteri',
        2: 'in neke ženske, ki so bile ozdravljene od zlih duhov in slabotnosti: Marija, imenovana Magdalena, iz katere je odšlo sedem hudičev',
        3: '§ in Joana, žena Herodovega oskrbnika Husa ter Suzana in mnoge druge, ki so mu služile iz svojega imetja.',
        4: 'In ko je bilo skupaj zbranih veliko ljudi in so prišli k njemu iz vsakega mesta, je spregovoril s prispodobo:',
        5: '»Sejalec je odšel ven sejat svoje seme in ko je sejal, je nekaj padlo poleg poti in to je bilo pomendrano in pozobala ga je perjad neba.',
        6: 'In nekaj je padlo na skalo in takoj, ko je pognalo, je ovenelo, ker mu je primanjkovalo vlage.',
        7: 'In nekaj je padlo med trnje in trnje je pognalo z njim ter ga zadušilo.',
        8: 'Drugo pa je padlo na dobro zemljo in pognalo ter obrodilo stoteren sad.« In ko je povedal te besede, je zaklical: »Kdor ima ušesa, da slišijo, naj posluša.«',
        9: 'Njegovi učenci pa so ga vprašali, rekoč: »Kaj bi bila ta prispodoba?«',
        10: 'In rekel je: »Vam je dano spoznati skrivnosti Božjega kraljestva, toda drugim v prispodobah; da z gledanjem ne bi mogli videti in s poslušanjem ne bi mogli razumeti.',
        11: 'Torej prispodoba je ta: ›Seme je Božja beseda.',
        12: 'Tisti ob poti so tisti, ki slišijo; potem pride hudič in iz njihovih src odvzema besedo, da ne bi verjeli in ne bi bili rešeni.',
        13: 'Tisti na skali so tisti, ki, ko slišijo, z radostjo sprejmejo besedo; in ti nimajo korenine, ki nekaj časa verujejo, ob času skušnjave pa padejo stran.',
        14: 'In to, kar je padlo med trnje, so tisti, ki, ko so slišali, gredo naprej in so zadušeni s skrbmi in bogastvi in užitki tega življenja in nobenega sadu ne privedejo do zrelosti.',
        15: 'Toda to, na dobri zemlji, so tisti, ki so z iskrenim in dobrim srcem slišali besedo, jo obdržali in s potrpežljivostjo prinašajo sad.‹',
        16: '›Nihče, ko je prižgal svetilko, je ne pokrije s posodo ali jo postavi pod posteljo, temveč jo postavi na svečnik, da tisti, ki vstopajo noter, lahko vidijo svetlobo.',
        17: 'Kajti nič ni skrito, kar ne bo razodeto niti ni nobena stvar skrita, da se ne bo izvedela in postala znana.‹',
        18: 'Pazite torej kako poslušate, kajti kdorkoli ima, njemu bo dano; kdorkoli pa nima, bo od njega vzeto celó to, kar se mu zdi, da ima.«',
        19: 'Tedaj so prišli k njemu njegova mati in njegovi bratje, pa zaradi gneče niso mogli priti do njega.',
        20: 'In povedano mu je bilo po nekom, ki je rekel: »Tvoja mati in tvoji bratje stojijo zunaj in te želijo videti.«',
        21: 'In odgovoril je ter jim rekel: »Moja mati in moji bratje so tisti, ki poslušajo Božjo besedo in jo izvršujejo.«',
        22: 'Pripetilo se je torej na nek dan, da je s svojimi učenci odšel na ladjo in jim rekel: »Pojdimo preko, na drugo stran jezera.« In so odrinili.',
        23: 'Toda ko so jadrali, je zaspal. Dol na jezero pa je prišel vetroven vihar in bili so napolnjeni z vodo in v nevarnosti.',
        24: 'In prišli so k njemu ter ga zbudili, rekoč: »Učitelj, učitelj, mi ginemo.« Potem je vstal, oštel veter in besnenje vode, in ponehala sta in bil je mir.',
        25: 'Rekel jim je: »Kje je vaša vera?« In prestrašeno začudeni so drug drugemu govorili: »Kakšne vrste človek je to! Kajti ukazuje celó vetrovom in vodi in so mu pokorni.«',
        26: 'In prispeli so v Géraško deželo, ki je na drugi strani, nasproti Galileji.',
        27: 'In ko je šel naprej v deželo, ga je tam zunaj mesta srečal nek mož, ki je imel dolgo časa hudiče in ni nosil oblačil niti ni prebival v nobeni hiši, temveč v grobnicah.',
        28: 'Ko je zagledal Jezusa, je zakričal in padel dol pred njim ter z močnim glasom rekel: »Kaj imam opraviti s teboj, Jezus, ti Sin od Boga najvišjega? Rotim te, ne muči me.«',
        29: '(Kajti nečistemu duhu je ukazal, da pride iz tega človeka. Kajti ta ga je pogosto zgrabil in bil je držan zvezan z verigami in okovi, pa je prelomil vezi in po hudiču je bil gnan v divjino.)',
        30: 'In Jezus ga je vprašal, rekoč: »Kako ti je ime?« In ta je rekel: »Legija,« ker je vanj vstopilo mnogo hudičev.',
        31: 'In rotili so ga, da jim ne bi ukazal oditi ven, v brezno.',
        32: 'Tam pa je bila čreda mnogih svinj, ki so se pasle na gori in rotili so ga, naj jim dovoli vstopiti vanje. In dovolil jim je.',
        33: 'Tedaj so hudiči odšli iz človeka in vstopili v svinje in čreda je silovito stekla navzdol po strmini v jezero in so se zadušile.',
        34: 'Ko so tisti, ki so jih hranili, videli, kaj je bilo storjeno, so pobegnili in odšli ter to povedali v mestu in na deželi.',
        35: 'Potem so odšli ven, da vidijo kaj je bilo storjeno in prišli so k Jezusu in našli človeka, iz katerega so odšli hudiči, sedečega pri Jezusovih stopalih, oblečenega in pri zdravi pameti, in bili so prestrašeni.',
        36: 'Tisti, ki so to videli, so jim povedali tudi na kakšen način je bil ta, ki je bil obseden s hudiči, ozdravljen.',
        37: '§ Potem ga je celotna množica naokoli iz Géraške dežele rotila, naj odide od njih, kajti bili so prevzeti z velikim strahom, on pa je odšel gor na ladjo in se ponovno vrnil nazaj.',
        38: 'Torej mož, iz katerega so izšli hudiči, ga je rotil, da bi bil lahko z njim, toda Jezus ga je poslal proč, rekoč:',
        39: '»Vrni se k svoji lastni hiši in pokaži, kako velike stvari ti je storil Bog.« In ta je odšel svojo pot ter po vsem mestu razglašal kako velike stvari mu je storil Jezus.',
        40: 'In pripetilo se je, ko se je Jezus vrnil, da ga je množica veselo sprejela, kajti vsi so ga pričakovali.',
        41: 'In glej, tja je prišel mož, po imenu Jaír in bil je predstojnik sinagoge in ta je padel dol k Jezusovim stopalom ter ga rotil, da bi prišel v njegovo hišo,',
        42: 'kajti imel je eno samo hčer, staro okoli dvanajst let in ta je umirala. Toda ko je šel, je množica pritiskala nanj.',
        43: 'In ženska, ki je dvanajst let imela težave s krvjo, ki je ves svoj dohodek potrošila za zdravnike niti je nihče ni mogel ozdraviti,',
        44: 'je prišla za njim ter se dotaknila roba njegove obleke in njena težava s krvjo se je takoj ustavila.',
        45: '§ In Jezus je rekel: »Kdo se me je dotaknil?« Ko so vsi zanikali, so Peter in tisti, ki so bili z njim, rekli: »Učitelj, množica te preriva in pritiska, ti pa praviš: ›Kdo se me je dotaknil?‹«',
        46: 'Jezus je rekel: »Nekdo se me je dotaknil, kajti zaznal sem, da je iz mene šla moč.«',
        47: 'In ko je ženska videla, da ni bila skrita, je trepetajoč prišla in padla dol pred njim. Pred vsemi ljudmi mu je priznala, zaradi kakšnega razloga se ga je dotaknila in kako je bila takoj ozdravljena.',
        48: '§ In rekel ji je: »Hči, bodi dobro potolažena. Tvoja vera te je ozdravila, pojdi v miru.«',
        49: 'Medtem ko je še govoril, pride tja nekdo iz hiše predstojnika sinagoge in mu reče: »Tvoja hči je mrtva, ne nadleguj Učitelja.«',
        50: 'Ko je Jezus to slišal, mu je odgovoril, rekoč: »Ne boj se, samo veruj in ozdravela bo.«',
        51: 'In ko je prišel v hišo, nobenemu človeku ni dovolil vstopiti noter, razen Petru, Jakobu in Janezu ter očetu in materi deklice.',
        52: 'In vsi so jokali ter jo objokovali, toda rekel je: »Ne jokajte. Ona ni mrtva, temveč spi.«',
        53: 'In smejali so se mu do norčevanja, ker so vedeli, da je bila mrtva.',
        54: 'In vse jih je postavil ven, jo prijel za roko in jo poklical, rekoč: »Deklica, vstani.«',
        55: 'In njen duh je ponovno prišel in nemudoma je vstala in ukazal je, naj ji dajo jesti.',
        56: 'In njena starša sta bila osupla, toda naročil jima je, naj nobenemu človeku ne povesta, kaj se je zgodilo.',
    },
    9: {
        1: 'Potem je sklical skupaj svoje dvanajstere učence in jim dal moč in oblast nad vsemi hudiči in za ozdravljanje bolezni.',
        2: 'In poslal jih je, da oznanjajo Božje kraljestvo in da ozdravljajo bolne.',
        3: 'Rekel jim je: »Za svoje potovanje ne vzemite ničesar, niti palic, prav tako ne malhe, niti kruha, niti denarja, niti ne imejte vsak po dva plašča.',
        4: 'In v katerokoli hišo vstopite, tam ostanite in od tam odidite.',
        5: 'Kdorkoli vas ne bo sprejel, kadar greste iz tega mesta, si iz svojih stopal otresite prav [ta] prah, v pričevanje proti njim.«',
        6: 'In odpravili so se in šli skozi mesta in oznanjali evangelij in povsod ozdravljali.',
        7: 'Torej Herod, vladar četrtinskega dela province, je slišal o vsem, kar je bilo storjeno po njem; in bil je zmeden, zato ker so nekateri rekli, da je bil Janez obujen od mrtvih,',
        8: 'in od nekaterih, da se je pojavil Elija in od drugih, da je vstal eden izmed starih prerokov.',
        9: 'Herod pa je rekel: »Janeza sem jaz obglavil, toda kdo je ta, o katerem slišim takšne stvari?« In želel si je, da bi ga videl.',
        10: 'In apostoli, ko so se vrnili, so mu povedali vse, kar so storili. In vzel jih je in odšel stran, na samo, v zapuščen kraj, ki je pripadal mestu z imenom Betsajda.',
        11: 'Ko je množica to izvedela, mu je sledila in sprejel jih je ter jim govoril o Božjem kraljestvu in ozdravil te, ki so imeli potrebo po ozdravljenju.',
        12: 'In ko je dan začel minevati, potem so prišli dvanajsteri ter mu rekli: »Pošlji množico proč, da lahko gredo v mesta in naokoli po deželi ter prenočijo in si preskrbijo živeža, kajti tukaj smo na samotnem kraju.«',
        13: 'Toda rekel jim je: »Vi jim dajte jesti.« Oni pa so rekli: »Nimamo več kot pet hlebov in dve ribi, razen, če bi šli in za vse te ljudi kupili hrano.«',
        14: 'Kajti bilo jih je okoli pet tisoč mož. In svojim učencem je rekel: »Primorajte jih, da se usedejo v skupine po petdeset.«',
        15: 'In storili so tako in vse so primorali sesti.',
        16: 'Tedaj je vzel pet hlebov in dve ribi in jih, zroč k nebu, blagoslovil in razlomil in dal učencem, da jih postavijo pred množico.',
        17: 'In jedli so in vsi so bili nasičeni. In od odlomkov, ki so jim ostali, je bilo nabranih dvanajst košar.',
        18: 'In pripetilo se je, ko je bil sam in molil, [da] so bili z njim njegovi učenci. In vprašal jih je, rekoč: »Kdo pravi množica, da sem jaz?«',
        19: 'Rekli so in odgovorili: »›Janez Krstnik,‹ toda nekateri pravijo: ›Elija‹ in drugi pravijo, da je vstal eden izmed starih prerokov.«',
        20: 'Rekel jim je: »Toda kdo vi pravite, da sem jaz?« Peter mu reče in odgovori: »Kristus od Boga.«',
        21: 'In strogo jim je naročil in jim ukazal, da te besede ne povedo nobenemu človeku,',
        22: 'rekoč: »Sin človekov mora pretrpeti mnoge stvari in biti zavrnjen od starešin in visokih duhovnikov in pisarjev in umorjen bo in tretji dan bo obujen.«',
        23: 'Njim vsem pa je rekel: »Če hoče katerikoli človek priti za menoj, naj se odpove samemu sebi in vsak dan vzame svoj križ ter mi sledi.',
        24: 'Kajti kdorkoli hoče rešiti svoje življenje, ga bo izgubil, toda kdorkoli hoče izgubiti svoje življenje zaradi mene, ta isti ga bo rešil.',
        25: 'Kajti kaj človeku koristi, če si pridobi ves svet, pa izgubi samega sebe ali je zavržen?',
        26: 'Kajti kdorkoli se bo sramoval mene in mojih besed, njega se bo sramoval Sin človekov, ko bo prišel v svoji lastni slavi in v [slavi] svojega Očeta in svetih angelov.',
        27: 'Toda povem vam po resnici, tam bo nekaj tukaj navzočih, ki ne bodo okusili smrti, dokler ne bodo videli Božjega kraljestva.«',
        28: 'In pripetilo se je okoli osmega dne po teh govorih, da je vzel Petra in Janeza in Jakoba ter odšel gor na goro, da moli.',
        29: 'In medtem ko je molil, je bil videz njegovega obličja predrugačen in njegova oblačila so bila bela in sijoča.',
        30: 'In glej, z njim sta govorila dva moža, ki sta bila Mojzes in Elija.',
        31: 'Prikazala sta se v slavi in govorila o njegovem odhodu, ki naj bi ga dovršil v Jeruzalemu.',
        32: 'Toda Peter in ta dva, ki sta bila z njim, so bili obteženi s spanjem. Ko so se zbudili, so videli njegovo slavo in dva moža, ki sta stala z njim.',
        33: 'In pripetilo se je, ko sta odšla od njega, da je Peter rekel Jezusu: »Učitelj, dobro je za nas, da smo tukaj. Naredimo tri šotore: enega zate in enega za Mojzesa in enega za Elija,« pa ni vedel, kaj je govoril.',
        34: 'Medtem ko je tako govoril, je prišel oblak in jih zasenčil in ko so vstopili v oblak, so se prestrašili.',
        35: 'In iz oblaka je prišel glas, rekoč: »Ta je moj ljubljeni Sin, njega poslušajte.«',
        36: 'In ko je glas minil, se je Jezus znašel sam. Oni pa so [to] obdržali zase in v tistih dneh nobenemu človeku niso povedali o teh stvareh, ki so jih videli.',
        37: 'In pripetilo se je, da ga je naslednji dan, ko so prišli dol s hriba, srečalo mnogo ljudi.',
        38: 'In glej, mož iz skupine je zavpil, rekoč: »Učitelj, rotim te, poglej na mojega sina, kajti on je moj edini otrok.',
        39: 'In glej, duh ga napada in nenadoma vpije in trga ga, da se ponovno peni in ko ga močno udari, odide od njega.',
        40: 'In rotil sem tvoje učence, da ga izženejo iz njega, pa niso mogli.«',
        41: 'Jezus pa odgovori in reče: »O neverni in sprevrženi rod, kako dolgo bom še z vami in vas prenašal? Privedi svojega sina sèm.«',
        42: 'In ko je šele prihajal, ga je hudič vrgel dol ter ga trgal. In Jezus je oštel nečistega duha in ozdravil otroka ter ga ponovno izročil njegovemu očetu.',
        43: 'In vsi so bili osupli nad mogočno Božjo močjo. Toda medtem ko so se vsi čudili ob vseh stvareh, ki jih je Jezus storil, je svojim učencem rekel:',
        44: '»Naj te besede prodrejo v vaša ušesa, kajti Sin človekov bo izročen v človeške roke.«',
        45: 'Toda tega govora niso razumeli in ta je bil skrit pred njimi, da ga niso zaznali in bali so se ga vprašati o tem govoru.',
        46: 'Potem je med njimi nastalo razmišljanje, kdo izmed njih naj bi bil največji.',
        47: 'In Jezus, zaznavajoč misel njihovega srca, je vzel otroka ter ga postavil poleg sebe',
        48: 'ter jim rekel: »Kdorkoli bo tega otroka sprejel v mojem imenu, sprejema mene in kdorkoli bo sprejel mene, sprejema tistega, ki me je poslal, kajti kdor je najmanjši med vami vsemi, ta isti bo velik.«',
        49: 'In Janez je odgovoril ter rekel: »Učitelj, nekoga smo videli v tvojem imenu izganjati hudiče in smo mu prepovedali, ker ne hodi skupaj z nami.«',
        50: '§ Toda Jezus mu je rekel: »Ne prepovejte mu, kajti kdor ni proti nam, je za nas.«',
        51: 'In pripetilo se je, ko je prišel čas, da naj bi bil sprejet gor, se je on neomajno odločil, da gre v Jeruzalem',
        52: 'in pred svojim obrazom je poslal poslance in ti so šli ter vstopili v vas Samarijanov, da pripravijo zanj.',
        53: '§ Oni pa ga niso sprejeli, ker je bil njegov obraz, kakor da hoče iti v Jeruzalem.',
        54: '§ In ko sta njegova učenca, Jakob in Janez, to videla, sta rekla: »Gospod, hočeš, da ukaževa ognju, da pride dol z neba in jih pogoltne, kakor je storil Elija?«',
        55: '§ Toda on se je obrnil in ju oštel ter rekel: »Vidva ne vesta, iz kakšne vrste duha sta.',
        56: '§ Kajti Sin človekov ni prišel, da pokonča človeška življenja, temveč, da jih reši.« In odšli so v drugo vas.',
        57: 'In pripetilo se je, ko so šli po poti, da mu je nek človek rekel: »Gospod, sledil ti bom, kamorkoli greš.«',
        58: 'In Jezus mu je rekel: »Lisice imajo luknje in ptice neba imajo gnezda, toda Sin človekov nima kam nasloniti svoje glave.«',
        59: 'In drugemu je rekel: »Sledi mi.« Vendar je ta rekel: »Gospod, dovoli mi najprej, da grem in pokopljem svojega očeta.«',
        60: 'Jezus mu je rekel: »Naj mrtvi pokopljejo svoje mrtve, ti pa pojdi in oznanjaj Božje kraljestvo.«',
        61: 'Prav tako je rekel drugi: »Gospod, sledil ti bom, toda naj grem najprej in se poslovim od teh, ki so doma v moji hiši.«',
        62: 'In Jezus mu je rekel: »Nihče, ki svojo roko položi na plug in gleda nazaj, ni primeren za Božje kraljestvo.«',
    },
    10: {
        1: '§ Po teh besedah je Gospod določil tudi drugih sedemdeset in jih poslal po dva in dva pred seboj v vsako mesto in kraj, kamor bi sam prišel.',
        2: 'Zato jim je rekel: »Žetev je resnično velika, toda delavcev je malo. Prosite torej Gospoda žetve, da bi poslal delavce na svojo žetev.',
        3: 'Pojdite [po] svojih poteh. Glejte, pošiljam vas kakor jagnjeta med volkove.',
        4: 'Ne nosite niti mošnje niti malhe niti čevljev in po poti ne pozdravljajte nobenega človeka.',
        5: 'In v katerokoli hišo vstopite, najprej recite: ›Mir bodi tej hiši.‹',
        6: 'In če bo tam sin miru, bo vaš mir počival na njej; če ne, se bo ponovno obrnil k vam.',
        7: 'In v isti hiši ostanite, jejte in pijte te stvari, ki vam jih dajo, kajti delavec je vreden svojega plačila. Ne hodite od hiše do hiše.',
        8: 'In v katerokoli mesto vstopite in vas sprejmejo, jejte te stvari, ki so postavljene pred vas',
        9: 'in ozdravljajte bolne, ki so v njem in govorite jim: ›Božje kraljestvo je prišlo blizu k vam.‹',
        10: 'Toda v katerokoli mesto vstopite in vas ne sprejmejo, pojdite po svojih poteh ven na ulice le-tega in recite:',
        11: '›Celo prav [ta] prah iz vašega mesta, ki se je [trdno] prilepil na nas, otresamo zoper vas. Vendar pa bodite prepričani o tem, da je Božje kraljestvo prišlo blizu k vam.‹',
        12: 'Toda povem vam, da bo na tisti dan bolj znosno za Sódomo kakor za to mesto.',
        13: 'Gorje ti, Horazín! Gorje ti, Betsajda! Kajti če bi bila ta mogočna dela, ki so bila storjena v tebi, storjena v Tiru in Sidónu, bi se že davno pokesala, sedeč v vrečevini in pepelu.',
        14: 'Toda ob sodbi bo bolj znosno za Tir in Sidón kakor za vaju.',
        15: 'In ti Kafarnáum, ki si vzvišen do neba, boš pahnjen navzdol do pekla.',
        16: 'Kdor posluša vas, posluša mene; kdor pa prezira vas, prezira mene; in kdor prezira mene, prezira tistega, ki me je poslal.«',
        17: '§ In sedemdeset se jih je ponovno vrnilo z radostjo, rekoč: »Gospod, celó hudiči so nam pokorni v tvojem imenu.«',
        18: 'Rekel jim je: »Gledal sem Satana kakor bliskanje pasti z neba.',
        19: '§ Glejte, dajem vam oblast, da stopate na kače in škorpijone in čez vso sovražnikovo oblast in nič vam ne bo na kakršenkoli način škodilo.',
        20: 'Vendar se ne veselite tega, da so vam duhovi podrejeni, temveč se raje veselite, ker so vaša imena zapisana v nebesih.«',
        21: 'V tej uri se je Jezus razveselil v duhu in rekel: »Zahvaljujem se ti, oh Oče, Gospodar neba in zemlje, da si te besede skril pred modrimi in razsodnimi, razodel pa si jih otročičem. Točno tako, Oče, kajti tako je bilo videti dobro v tvojih očeh.',
        22: 'Vse stvari so mi izročene od mojega Očeta in noben človek ne ve, kdo je Sin, razen Očeta in kdo je Oče, razen Sina in tistega, ki mu ga bo Sin razodel.«',
        23: 'In obrnil se je k svojim učencem in na samem rekel: »Blagoslovljene so oči, ki vidijo stvari, ki jih vi vidite,',
        24: 'kajti povem vam, da je mnogo prerokov in kraljev želelo videti te stvari, ki jih vi vidite, pa jih niso videli, in slišati te besede, ki jih vi slišite, pa jih niso slišali.«',
        25: 'In glej, nek izvedenec v postavi je vstal ter ga skušal, rekoč: »Učitelj, kaj naj storim, da podedujem večno življenje?«',
        26: 'Rekel mu je: »Kaj je zapisano v postavi? Kako bereš?«',
        27: 'In ta odgovori in reče: »Gospoda svojega Boga boš ljubil z vsem svojim srcem in z vso svojo dušo in z vso svojo močjo in z vsem svojim mišljenjem, in svojega bližnjega kakor samega sebe.«',
        28: 'In rekel mu je: »Prav si odgovoril. To delaj in boš živel.«',
        29: 'Toda ker je hotel opravičiti samega sebe, je Jezusu rekel: »In kdo je moj bližnji?«',
        30: 'In Jezus mu odgovori ter reče: »Neki človek je šel iz Jeruzalema navzdol v Jeriho in padel med tatove, ki so mu slekli njegova oblačila in ga ranili in odšli ter ga pustili napol mrtvega.',
        31: 'In po naključju pride dol po tej poti nek duhovnik; in ko ga je zagledal, je po drugi strani šel mimo.',
        32: 'In podobno je Lévijevec, ko je bil na tem kraju, prišel ter pogledal nanj in šel mimo po drugi strani.',
        33: 'Toda nek Samarijan, ki je potoval, je prišel tja, kjer je bil, in ko ga je zagledal, je imel do njega sočutje',
        34: 'in šel k njemu ter povezal njegove rane, izlivajoč vanje olja in vina in ga namestil na svojo lastno žival ter ga privedel do gostišča in zanj poskrbel.',
        35: 'In naslednjega dne, ko je odšel, je vzel ven dva denarja in ju dal gostilničarju ter mu rekel: ›Poskrbi zanj in karkoli porabiš več, ti bom poplačal, ko ponovno pridem.‹',
        36: '›Kaj meniš, kateri torej od teh treh je bil bližnji temu, ki je padel med tatove?‹«',
        37: 'In ta je rekel: »Kdor mu je izkazal usmiljenje.« Potem mu je Jezus rekel: »Pojdi in ti delaj enako.«',
        38: 'Pripetilo se je torej, ko so šli, da je vstopil v neko vas in neka ženska, po imenu Marta, ga je sprejela v svojo hišo.',
        39: 'In imela je sestro, po imenu Marija, ki je prav tako sedla k Jezusovim stopalom in poslušala njegovo besedo.',
        40: 'Toda Marta je bila obremenjena glede tolikšne postrežbe in je prišla k njemu ter rekla: »Gospod, ti ni mar, da me je moja sestra pustila, da sama strežem? Ukaži ji vendar, naj mi pomaga.«',
        41: '§ Jezus pa je odgovoril ter ji rekel: »Marta, Marta, vznemirjaš se in skrbiš glede mnogih stvari.',
        42: 'Toda ena stvar je potrebna in Marija si je izbrala ta dobri del, ki od nje ne bo odvzet.«',
    },
    11: {
        1: 'In pripetilo se je, medtem ko je na nekem kraju molil, ko je prenehal, da mu je eden izmed njegovih učencev rekel: »Gospod, nauči nas moliti, kakor je tudi Janez naučil svoje učence.«',
        2: '§ Rekel jim je: »Kadar vi molite, recite: ›Naš Oče, ki si v nebesih: ›Posvečuje naj se tvoje ime. Pridi tvoje kraljestvo. Zgôdi se tvoja volja, kakor je v nebesih, tako na zemlji.',
        3: 'Daj nam dan za dnem naš vsakdanji kruh.',
        4: '§ In odpusti nam naše grehe, kajti tudi mi odpuščamo vsakemu, ki nam je dolžan. In ne vôdi nas v skušnjavo, temveč nas osvobodi pred zlom.‹«',
        5: 'In rekel jim je: »Kateri izmed vas bo imel prijatelja in bo šel k njemu ob polnoči ter mu rekel: ›Prijatelj, posodi mi tri hlebe,',
        6: 'kajti moj prijatelj je na svojem potovanju prišel k meni, pa nimam ničesar, da postavim predenj?‹',
        7: 'In ta od znotraj bo odgovoril ter rekel: ›Ne moti me. Vrata so sedaj zaprta in moji otroci so z menoj v postelji. Ne morem vstati in ti dati.‹',
        8: 'Povem vam: ›Čeprav ne bo vstal in mu dal, ker je njegov prijatelj, bo vendarle vstal zaradi njegove vsiljivosti ter mu dal toliko, kolikor potrebuje.‹',
        9: 'In jaz vam pravim: ›Prosite in to vam bo dano. Iščite in boste našli. Trkajte in to se vam bo odprlo.‹',
        10: 'Kajti vsak, kdor prosi, prejema; in kdor išče, najde; in tistemu, ki trka, se bo odprlo.',
        11: '§ Če bo sin kogarkoli izmed vas, ki je oče, prosil kruha ali mu bo dal kamen? Ali če prosi ribe ali mu bo namesto ribe dal kačo?',
        12: 'Ali če bo prosil jajce ali mu bo ponudil škorpijona?',
        13: 'Če torej vi, ki ste hudobni, veste kako dajati svojim otrokom dobre darove, koliko bolj bo vaš nebeški Oče dal Svetega Duha tistim, ki ga prosijo?«',
        14: 'In izganjal je hudiča, ta pa je bil nem. In pripetilo se je, ko je hudič odšel ven, [da] je nemi spregovoril in množica se je čudila.',
        15: 'Toda nekateri izmed njih so rekli: »Hudiče izganja preko Bélcebuba, vodilnega izmed hudičev.«',
        16: 'In drugi so ga skušali in od njega hoteli znamenje z neba.',
        17: 'Vendar jim je on, ker je poznal njihove misli, rekel: »Vsako kraljestvo, razdvojeno zoper sebe, je privedeno v opustošenje; in hiša, razdvojena zoper hišo, pade.',
        18: 'Če bi bil tudi Satan razdeljen zoper samega sebe, kako bi obstalo njegovo kraljestvo, ker pravite, da s pomočjo Bélcebuba izganjam hudiče?',
        19: 'In če jaz z Bélcebubom izganjam hudiče, s kom [jih] izganjajo vaši sinovi? Zatorej bodo oni vaši sodniki.',
        20: '§ Toda če jaz z Božjim prstom izganjam hudiče, je brez dvoma nad vas prišlo Božje kraljestvo.',
        21: 'Ko močan mož oborožen čuva svojo palačo, so njegove dobrine v miru,',
        22: 'toda ko bo nadenj prišel močnejši od njega in ga premagal, mu odvzame vso njegovo bojno opremo, v katero je zaupal in razdeli njegove plene.',
        23: 'Kdor ni z menoj, je proti meni, in kdor ne zbira z menoj, raztresa.',
        24: 'Ko je nečisti duh odšel iz človeka, hodi skozi suhe kraje, iščoč počitka; ker pa ga ne najde, pravi: ›Vrnil se bom k svoji hiši, od koder sem prišel ven.‹',
        25: 'In ko pride, jo najde pometeno in okrašeno.',
        26: 'Tedaj gre in vzame k sebi sedem drugih duhov, zlobnejših kakor on sam; in vstopijo vanjo ter tam prebivajo in zadnje stanje tega človeka je hujše kakor prvo.«',
        27: 'In pripetilo se je, medtem ko je govoril te besede, [da] je neka ženska iz skupine povzdignila svoj glas in mu rekla: »Blagoslovljena je maternica te, ki te je nosila in prsi, ki si jih sesal.«',
        28: 'Toda rekel je: »Da, toliko bolj blagoslovljeni so tisti, ki poslušajo Božjo besedo in se je držijo.«',
        29: 'In ko je bila množica zbrana tesno skupaj, je začel govoriti: »To je hudoben rod. Iščejo znamenje, pa jim ne bo dano nobeno znamenje, razen znamenja preroka Jona.',
        30: 'Kajti kakor je bil Jona znamenje Ninivljanom, tako bo tudi Sin človekov temu rodu.',
        31: 'Kraljica juga bo ob sodbi vstala z ljudmi tega rodu in jih obsodila, kajti prišla je iz skrajnih delov zemlje, da sliši Salomonovo modrost; in glejte, večji kakor Salomon je tukaj.',
        32: 'Ljudje iz Niniv bodo ob sodbi vstali s tem rodom in ga obsodili, kajti pokesali so se ob Jonovem oznanjevanju; in glejte, večji kakor Jona je tukaj.',
        33: 'Nihče, ko je prižgal svetilko, je ne položi na skrivno mesto niti ne pod mernik, temveč na svečnik, da tisti, ki vstopajo, lahko vidijo svetlobo.',
        34: '§ Svetloba telesa je oko. Ko je torej tvoje oko enovito, je tudi tvoje celó telo polno svetlobe, toda kadar je tvoje oko hudobno, je tudi tvoje telo polno teme.',
        35: 'Pazite torej potemtakem, da svetloba, ki je v tebi, ne bo tema.',
        36: 'Če je torej tvoje celotno telo polno svetlobe in nima nobenega dela temnega, bo vse polno svetlobe, kot kadar ti lesketajoče sijanje svečnika daje svetlobo.«',
        37: 'In medtem ko je govoril, ga je nek farizej rotil, naj obeduje z njim. In vstopil je ter se usedel k obedu.',
        38: 'Ko je farizej to videl, se je čudil, da se pred obedom ni najprej umil.',
        39: 'Gospod pa mu je rekel: »Torej vi farizeji čistite zunanjost čaše in pladnja, toda vaš notranji del je poln požrešnosti in zlobnosti.',
        40: 'Vi bedaki, mar ni tisti, ki je naredil to, kar je zunaj, naredil tudi tega, kar je znotraj?',
        41: 'Toda raje dajte miloščino od takih stvari, kot jih imate, in glejte, vse stvari so vam čiste.',
        42: 'Toda gorje vam, farizeji! Kajti desetinite meto in ruto ter vse vrste zelišč, prezirate pa sodbo in Božjo ljubezen; te bi morali imeti narejene in ne pustiti drugih nenarejenih.',
        43: 'Gorje vam, farizeji! Ker ljubite najvišje sedeže v sinagogah in pozdrave na trgih.',
        44: '§ Gorje vam, pisarji in farizeji, hinavci! Kajti vi ste kakor grobovi, ki se ne razločijo in ljudje, ki hodijo čeznje, se jih ne zavedajo.«',
        45: 'Potem je odgovoril eden izmed izvedencev v postavi in mu rekel: »Učitelj, s takšnim govorjenjem grajaš tudi nas.«',
        46: 'On pa je rekel: »Gorje tudi vam, vi, izvedenci v postavi! Kajti ljudi natovarjate z bremeni, bridkimi za prenašanje, vi sami pa se niti z enim izmed svojih prstov ne dotaknete teh bremen.',
        47: 'Gorje vam! Kajti prerokom gradite mavzoleje, vaši očetje pa so jih ubili.',
        48: 'Resnično, vi pričujete, da odobravate dejanja svojih očetov; kajti zares so jih ubili, vi pa gradite njihove mavzoleje.',
        49: 'Zaradi tega je tudi Božja modrost rekla: ›Poslala jim bom preroke in apostole in nekatere izmed njih bodo ubili in preganjali,',
        50: 'da bo od tega rodu lahko zahtevana kri vseh prerokov, ki je bila prelita od ustanovitve sveta;',
        51: 'od krvi Abela do krvi Zaharija, ki je umrl med oltarjem in templjem.‹ Resnično, povem vam: ›Zahtevala se bo od tega rodu.‹',
        52: 'Gorje vam, izvedenci v postavi! Kajti odvzeli ste ključ spoznanja. Sami niste vstopili, tem, ki so vstopali, pa ste preprečevali.«',
        53: 'In ko jim je povedal te besede, so ga pisarji in farizeji začeli silovito nagovarjati in ga izzivati, da bi govoril o mnogih stvareh,',
        54: '§ ker so prežali nanj in si prizadevali, da ujamejo kaj iz njegovih ust, da bi ga lahko obtožili.',
    },
    12: {
        1: 'Medtem ko je bila tam skupaj zbrana brezštevilna množica ljudstva, do take mere, da so stopali drug po drugem, je najprej začel govoriti svojim učencem: »Pazite se kvasa farizejev, ki je hinavščina.',
        2: 'Kajti nič ni prikrito, kar ne bo razkrito niti skrito, kar se ne bo izvedelo.',
        3: 'Zatorej karkoli ste govorili v temi, bo slišano na svetlobi; in to, kar ste govorili v sobicah na ušesa, bo razglašeno na hišnih strehah.',
        4: 'Vam, svojim prijateljem, pa pravim: ›Ne bojte se teh, ki ubijejo telo in nató ne morejo nič več storiti.‹',
        5: 'Toda posvaril vas bom, koga se bojte: ›Bojte se njega, ki ima, potem ko je ubil, oblast, da vrže v pekel.‹ Da, pravim vam: ›Bojte se ga.‹',
        6: 'Ali ni pet vrabcev prodanih za dva novčiča, pa niti eden izmed njih ni pozabljen pred Bogom?',
        7: 'Toda celó vsi lasje vaše glave so prešteti. Ne bojte se torej, vredni ste več kakor mnogo vrabcev.',
        8: 'Prav tako vam pravim: ›Kdorkoli me bo priznal pred ljudmi, njega bo prav tako Sin človekov priznal pred Božjimi angeli,‹',
        9: 'toda kdor me zanika pred ljudmi, bo zanikan pred Božjimi angeli.',
        10: 'In kdorkoli bo govoril besedo zoper Sina človekovega, mu bo odpuščeno, toda tistemu, ki preklinja zoper Svetega Duha, ne bo odpuščeno.',
        11: 'In ko vas privedejo v sinagoge in k sodnikom in oblastem, se ne vznemirjajte in ne skrbite kakšno ali katero besedo boste odgovorili ali kaj boste rekli,',
        12: 'kajti Sveti Duh vas bo v tej isti uri poučil, kaj morate reči.«',
        13: 'Eden iz skupine pa mu je rekel: »Učitelj, spregovori mojemu bratu, naj dediščino deli z menoj.«',
        14: 'Rekel mu je: »Človek, kdo me je naredil sodnika ali delivca nad vama?«',
        15: 'In rekel jim je: »Pazite in čuvajte se pohlepnosti, kajti bistvo človeškega življenja ni v obilju stvari, ki jih poseduje.«',
        16: 'In povedal jim je prispodobo, rekoč: »Zemlja nekega bogataša je obilno obrodila',
        17: 'in mislil si je sam pri sebi, rekoč: ›Kaj bom storil, ker nimam prostora, kamor bi spravil svoje sadove?‹',
        18: 'Pa je rekel: ›To bom storil, podrl bom svoje skednje in zgradil večje in tja bom spravil vse svoje sadove in svoje dobrine.‹',
        19: 'Svoji duši pa bom rekel: ›Duša, veliko dobrin imaš spravljenih za mnogo let; vzemi si počitek, jej, pij in bodi vesela.‹',
        20: 'Toda Bog mu je rekel: ›Ti bedak, to noč bo tvoja duša zahtevana od tebe. Čigave bodo potem te stvari, ki si jih priskrbel?‹',
        21: 'Tak je, kdor zaklade shranjuje zase, ni pa bogat pred Bogom.«',
        22: 'Svojim učencem pa je rekel: »Zatorej vam pravim: ›Ne vznemirjajte se in ne skrbite za svoje življenje, kaj boste jedli; niti za telo, kaj boste oblekli.',
        23: 'Življenje je več kakor hrana in telo je več kakor oblačilo.',
        24: 'Preudarite o krokarjih, kajti niti ne sejejo niti ne žanjejo; ki nimajo niti skladišča niti skednja, pa jih Bog hrani. Kako silno ste vi boljši kakor perjad?',
        25: '§ In kdo izmed vas lahko z vznemirjanjem in skrbmi svoji postavi doda en komolec?',
        26: 'Če torej niste zmožni storiti te stvari, ki je najmanj pomembna, zakaj se vznemirjate in skrbite za ostalo?',
        27: 'Preudarite lilije, kako rastejo; ne garajo, ne predejo in vendar vam jaz pravim, da Salomon v vsej svoji slavi ni bil oblečen kakor ena izmed teh.',
        28: 'Če torej Bog tako oblači travo, ki je danes na polju in je jutri vržena v peč; kako mnogo bolj bo oblačil vas, oh vi maloverni?',
        29: 'In ne iščite, kaj boste jedli ali kaj boste pili niti ne bodite dvomljivega mišljenja.',
        30: 'Kajti za vsemi temi stvarmi povprašujejo narodi sveta in vaš Oče ve, da imate potrebo za temi stvarmi.',
        31: 'Toda raje iščite Božje kraljestvo in vse te stvari vam bodo dodane.',
        32: 'Ne bojte se, mali trop, kajti dobra volja vašega Očeta je, da vam da kraljestvo.',
        33: 'Prodajte, kar imate in dajte miloščino. Priskrbite si mošnje, ki ne ostarijo, zaklad v nebesih, ki ne izneveri, kjer se noben tat ne približa niti molj ne razkraja.',
        34: 'Kajti kjer je vaš zaklad, tam bo tudi vaše srce.',
        35: 'Naj bodo vaša ledja opasana in vaše svetilke prižgane,',
        36: 'vi sami pa podobni ljudem, ki čakajo na svojega gospodarja, kdaj se bo vrnil s poroke, da kadar pride in potrka, mu lahko takoj odprejo.',
        37: 'Blagoslovljeni so tisti služabniki, ki jih bo gospodar, ko pride, našel čuječe. Resnično, pravim vam, da se bo opasal in jih primoral, da se usedejo k obedu in bo prišel naprej ter jim stregel.',
        38: 'In če bo prišel ob drugi straži ali če pride ob tretji straži in jih najde takó, blagoslovljeni so tisti služabniki.',
        39: 'In vedite to, da če bi hišni oče vedel, katero uro bi prišel tat, bi stražil in ne bi dovolil, da bi bila njegova hiša vlomljena.',
        40: 'Bodite torej tudi vi pripravljeni, kajti Sin človekov prihaja ob uri, za katero ne mislite.‹«',
        41: 'Potem mu je Peter rekel: »Gospod, govoriš to prispodobo nam ali celó vsem?«',
        42: 'Gospod pa je rekel: »Kdo je potem tisti zvesti in modri oskrbnik, ki ga bo njegov gospodar naredil za vladarja nad njegovo družino, da jim ob pravšnjem obdobju da njihove deleže hrane?',
        43: 'Blagoslovljen je tisti služabnik, ki ga bo njegov gospodar, ko pride, našel tako početi.',
        44: 'Resnično vam povem, da ga bo naredil za vladarja nad vsem, kar ima.',
        45: 'Toda če pa ta služabnik v svojem srcu reče: ›Moj gospodar odlaša svoj prihod‹ in bo začel pretepati sluge in dekle, jesti in piti ter biti pijan,',
        46: 'bo gospodar tega služabnika prišel na dan, ko ga ne pričakuje in ob uri, ki se je ne zaveda in ga bo razsekal narazen ter mu določil njegov delež z neverniki.',
        47: 'Ta služabnik pa, ki je poznal voljo svojega gospodarja in se ni pripravil niti ni storil glede na njegovo voljo, bo pretepen z mnogimi udarci biča.',
        48: 'Toda kdor ni vedel, pa je zagrešil stvari, vredne bičanja, bo pretepen z malo udarci biča. Kajti komurkoli je mnogo dano, se bo od njega mnogo zahtevalo, in komur so ljudje mnogo izročili, bodo od njega terjali tem več.',
        49: 'Prišel sem, da pošljem ogenj na zemljo in kako si želim, da bi bil ta prižgan?',
        50: '§ Toda imam krst, da bom z njim krščen in kako sem omejen, dokler se to ne dovrši!',
        51: 'Mislite, da sem prišel, da dam mir na zemljo? Povem vam: ›Ne, temveč prej razkol,',
        52: 'kajti odslej jih bo v eni hiši pet razdeljenih, trije proti dvema in dva proti trem.',
        53: 'Oče bo razdeljen proti sinu in sin proti očetu; mati proti hčeri in hči proti materi; tašča proti snahi in snaha proti svoji tašči.‹',
        54: 'Množici pa je rekel tudi: ›Ko vidite oblak dvigati se iz zahoda, nemudoma pravite: ›Dež prihaja,‹ in tako se zgodi.',
        55: 'In ko vidite pihati južni veter, pravite: ›Vroče bo,‹ in tako se pripeti.',
        56: 'Vi hinavci, lahko razpoznate obličje neba in zemlje, toda kako to, da ne razpoznate tega časa?',
        57: 'Da, in zakaj celó sami od sebe ne sodite, kar je prav?',
        58: 'Ko greš s svojim nasprotnikom k oblastniku, ko si še na poti, se posveti prizadevanju, da boš lahko osvobojen pred njim; da te ta ne bi privlekel k sodniku in sodnik te izroči častniku, častnik pa te vrže v ječo.',
        59: 'Povem ti; ne boš odšel od tam, dokler ne odplačaš tudi zadnjega kovanca.«',
    },
    13: {
        1: 'Ob tistem času jih je bilo tam prisotnih nekaj, ki so mu povedali o Galilejcih, katerih kri je Pilat pomešal z njihovimi žrtvami.',
        2: 'Jezus pa jim odgovori in reče: »Mislite, da so bili ti Galilejci večji grešniki kakor vsi Galilejci, ker so pretrpeli te stvari?',
        3: 'Povem vam: ›Ne. Toda razen če se ne pokesate, boste vsi enako pokončani.‹',
        4: 'Ali tistih osemnajst, na katere je padel stolp v Síloi in jih usmrtil, mislite, da so bili večji grešniki od vseh ljudi, ki prebivajo v Jeruzalemu?',
        5: 'Povem vam: ›Ne. Toda razen če se ne pokesate, boste vsi enako pokončani.‹«',
        6: 'Povedal je tudi to prispodobo: »Neki človek je imel v svojem vinogradu posajeno figovo drevo in je prišel ter na njem iskal sadeža, pa ni našel nobenega.',
        7: 'Potem je rekel obrezovalcu trte svojega vinograda: ›Glej, ta tri leta sem prihajal in iskal sadu na tem figovem drevesu, pa ga nisem našel. Posekaj ga, čemú bremeni zemljo?‹',
        8: 'Ta pa odgovori in mu reče: ›Gospod, pusti jo še letos, da jo okopljem in pognojim',
        9: 'in če obrodi sad, dobro, če pa ne, jo boš torej potem posekal.‹«',
        10: 'In na šabat je učil v eni izmed sinagog.',
        11: 'In glej, tam je bila ženska, ki je osemnajst let imela duha šibkosti in je bila sključena in se nikakor ni mogla sama vzravnati.',
        12: 'In ko jo je Jezus zagledal, jo je poklical k sebi ter ji rekel: »Ženska, odvezana si od svoje šibkosti.«',
        13: 'In nanjo je položil svoje roke in takoj je postala vzravnana ter slavila Boga.',
        14: 'Predstojnik sinagoge pa je odgovoril z ogorčenjem, zato ker je Jezus zdravil na šabatni dan in rekel množici: »Šest dni je, v katerih morajo ljudje delati, v teh torej pridite in bodite zdravljeni, ne pa na šabatni dan.«',
        15: 'Potem mu je Gospod odgovoril in rekel: » Ti hinavec ali ne odveže vsak izmed vas na šabat svojega vola ali svojega osla od jasli in ga vodi proč napajat?',
        16: 'In ali ne bi morala biti ta ženska, ki je Abrahamova hči, ki jo je imel Satan zvezano, glejte, teh osemnajst let, odvezana te vezi na šabatni dan?«',
        17: 'Ko je povedal te stvari, so bili vsi njegovi nasprotniki osramočeni in vsa množica se je veselila zaradi vseh teh veličastnih stvari, ki so bile narejene po njem.',
        18: 'Tedaj je rekel: »Čému je podobno Božje kraljestvo? In s čim naj ga primerjam?',
        19: 'Podobno je zrnu gorčičnega semena, ki ga je človek vzel in ga vrgel na svoj vrt, in to je zraslo ter se razvilo v veliko drevo in na njegovih mladikah je prenočevala perjad neba.«',
        20: 'In ponovno je rekel: »Čému naj primerjam Božje kraljestvo?',
        21: 'Podobno je kvasu, ki ga je ženska vzela in skrila v treh merah moke, dokler ni bilo vse prekvašeno.«',
        22: 'On pa je šel skozi mesta in vasi ter učil in potoval proti Jeruzalemu.',
        23: 'Tedaj mu je nekdo rekel: »Gospod ali je malo teh, ki bodo rešeni?« On pa jim je rekel:',
        24: '»Prizadevajte si, da vstopite pri ozkih vratih, kajti povem vam, mnogi bodo poskušali vstopiti, pa ne bodo mogli.',
        25: 'Ko enkrat hišni gospodar vstane in zapre vrata, pričnete stati zunaj ter trkati na vrata, rekoč: ›Gospod, Gospod, odpri nam,‹ on pa vam bo odgovoril in rekel: ›Ne poznam vas, od kod ste.‹',
        26: 'Tedaj boste začeli govoriti: ›V tvoji prisotnosti smo jedli in pili in na naših ulicah si učil.‹',
        27: 'Toda rekel vam bo: ›Povem vam, ne vem, od kod ste; odidite od mene, vsi vi delavci krivičnosti.‹',
        28: 'Tam bo jokanje in škripanje z zobmi, ko boste videli Abrahama, Izaka in Jakoba ter vse preroke v Božjem kraljestvu, vas same pa pahnjene ven.',
        29: 'In prišli bodo od vzhoda in od zahoda in od severa in od juga in usedli se bodo v Božjem kraljestvu.',
        30: 'In glej, so zadnji, ki bodo prvi in so prvi, ki bodo zadnji.«',
        31: 'Istega dne so prišli tja nekateri izmed farizejev, rekoč mu: »Pojdi ven in odidi od tod, kajti Herod te hoče ubiti.«',
        32: '§ On pa jim je rekel: »Pojdite in povejte temu lisjaku: ›Glej, izganjam hudiče in ozdravljam danes in jutri, tretji dan pa bom dovršen.‹',
        33: 'Vendar moram danes in jutri in naslednji dan hoditi, kajti ni mogoče, da prerok umre zunaj Jeruzalema.',
        34: 'Oh Jeruzalem, Jeruzalem, ki ubijaš preroke in kamnaš tiste, ki so poslani k tebi; kako pogosto sem hotel zbrati tvoje otroke skupaj, kakor koklja zbira svoj zarod pod svoje peruti, pa niste hoteli!',
        35: 'Glejte, vaša hiša vam ostane zapuščena in resnično vam pravim: ›Ne boste me videli, dokler ne pride čas, ko boste rekli: ›Blagoslovljen je, kdor prihaja v Gospodovem imenu.‹«',
    },
    14: {
        1: 'In pripetilo se je, medtem ko je odšel v hišo enega izmed vodilnih farizejev, da bi na šabatni dan jedel kruh, da so ga ti opazovali.',
        2: 'In glej, pred njim je bil nek človek, ki je imel vodenico.',
        3: 'In Jezus je izvedencem v postavi in farizejem odgovarjal ter govoril, rekoč: »Ali je zakonito zdraviti na šabatni dan?«',
        4: 'Oni pa so molčali. In prijel ga je in ozdravil ter ga pustil oditi,',
        5: '§ in odgovoril jim je, rekoč: »Komu izmed vas pade osel ali vol v jamo in ga ne bo nemudoma, na šabatni dan, izvlekel ven?«',
        6: 'In ponovno mu niso mogli odgovoriti na te stvari.',
        7: 'In ko je opazil, kako izbirajo vodilna mesta, je tem, ki so bili povabljeni, podal prispodobo, rekoč jim:',
        8: '»Kadar te katerikoli človek povabi na poroko, se ne usedi na najvišje mesto, da ne bi le-ta povabil častitljivejšega človeka, kakor si ti,',
        9: 'in ne bi prišel ta, ki je povabil tebe in njega in ti rekel: ›Daj prostor temu človeku,‹ ti pa si boš s sramoto začel jemati najnižji prostor.',
        10: 'Toda kadar si povabljen, pojdi in se usedi na najnižji prostor, da ti lahko reče, kdor te je povabil, ko pride k tebi: ›Prijatelj, pojdi višje,‹ potem boš imel oboževanje v prisotnosti teh, ki s teboj sedijo pri obedu.',
        11: 'Kajti kdorkoli se povišuje, bo ponižan, kdor pa se ponižuje, bo povišan.«',
        12: 'Potem je prav tako rekel tistemu, ki ga je povabil: »Kadar pripravljaš kosilo ali večerjo, ne pokliči svojih prijateljev, niti svojih bratov, niti svojih sorodnikov, niti svojih bogatih sosedov, da te ne bi tudi oni povabili in ti povrnili.',
        13: 'Toda kadar pripravljaš pojedino, pokliči revne, pohabljene, hrome, slepe',
        14: 'in boš blagoslovljen, ker ti ne morejo poplačati, kajti poplačano ti bo ob vstajenju pravičnih.«',
        15: 'In ko je eden izmed teh, ki je pri obedu sedel z njim, slišal te stvari, mu je rekel: »Blagoslovljen je, kdor bo jedel kruh v Božjem kraljestvu.«',
        16: 'On pa mu je potem rekel: »Neki človek je priredil veliko večerjo in povabil mnoge.',
        17: 'Ob času večerje pa je poslal svojega služabnika, da pove tem, ki so bili povabljeni: ›Pridite, kajti sedaj so vse stvari pripravljene.‹',
        18: 'Vsi pa so se začeli soglasno opravičevati. Prvi mu je rekel: ›Kupil sem kos zemlje in nujno ga moram iti pogledat. Prosim te, imej me za opravičenega.‹',
        19: 'In drugi je rekel: ›Kupil sem pet jarmov volov in grem, da jih preizkusim. Prosim te, imej me za opravičenega.‹',
        20: 'In drugi je rekel: ›Poročil sem ženo in zato ne morem priti.‹',
        21: 'Tako, da je ta služabnik prišel in te stvari sporočil svojemu gospodarju. Potem je hišni gospodar jezen rekel svojemu služabniku: ›Pojdi hitro ven na ulice in mestne ceste ter pripelji sèm revne in pohabljene in šepave in slepe.‹',
        22: 'In služabnik je rekel: ›Gospod, narejeno je, kakor si zapovedal in še je prostor.‹',
        23: 'In gospodar je rekel služabniku: ›Pojdi ven na glavne ceste ter ograje in jih prisili, da vstopijo, da se bo moja hiša lahko napolnila.‹',
        24: 'Kajti povem vam: ›Da nihče izmed tistih ljudi, ki so bili povabljeni, ne bo okusil moje večerje.‹«',
        25: 'In z njim so šle velike množice, on pa se je obrnil in jim rekel:',
        26: '»Če katerikoli človek pride k meni in ne sovraži svojega očeta in matere in žene in otrok in bratov in sester, da in tudi svojega lastnega življenja, ne more biti moj učenec.',
        27: 'In kdorkoli ne nosi svojega križa in ne sledi meni, ne more biti moj učenec.',
        28: 'Kajti kdo izmed vas, ki hoče zgraditi stolp, se prej ne usede in ne prešteje stroška, ali ima zadosti, da ga dokonča?',
        29: 'Da ga ne bi morda potem, ko je položil temelj, pa ga ne bi bil zmožen dokončati, vsi tisti, ki so to gledali, začeli zasmehovati,',
        30: 'rekoč: ›Ta človek je začel graditi, pa ni bil zmožen dokončati.‹',
        31: 'Ali kateri kralj, ki pripravlja vojno proti drugemu kralju, prej ne séde in se posvetuje, če bo zmožen z deset tisoči srečati tistega, ki prihaja nadenj z dvajsetimi tisoči?',
        32: 'Sicer, dokler je drugi še daleč, on pošlje poslanstvo in prosi pogoje za mir.',
        33: 'Torej podobno, kdorkoli izmed vas, ki ne zapusti vsega, kar ima, ne more biti moj učenec.',
        34: 'Sol je dobra, toda če je sol izgubila svoj okus, s čim se bo začinila?',
        35: 'Niti ni primerna za zemljo niti za gnojišče, temveč jo ljudje mečejo ven. Kdor ima ušesa, da slišijo, naj posluša.«',
    },
    15: {
        1: 'Potem so se mu približali vsi davkarji in grešniki, da bi ga poslušali.',
        2: 'Farizeji in pisarji pa so godrnjali, rekoč: »Ta človek sprejema grešnike in z njimi jé.«',
        3: 'Povedal pa jim je to prispodobo, rekoč:',
        4: '»Kateri mož izmed vas, ki ima sto ovac, če izgubi eno izmed njih, ali ne bo zapustil devetindevetdesetih v divjini in šel za to, ki je izgubljena, dokler je ne najde?',
        5: 'In ko jo najde, jo vesel naprti na svoja ramena.',
        6: 'In ko pride domov, skliče skupaj svoje prijatelje ter sosede, rekoč jim: ›Veselite se z menoj, kajti našel sem svojo ovco, ki je bila izgubljena.‹',
        7: 'Povem vam, da bo na nebu podobna radost nad enim grešnikom, ki se pokesa, bolj kakor nad devetindevetdesetimi pravičnimi osebami, ki ne potrebujejo kesanja.',
        8: 'Ali katera ženska, ki ima deset koščkov srebra, če izgubi en košček ali ne prižge svetilke in ne pomete hiše in marljivo išče, dokler ga ne najde?',
        9: 'Ko pa ga je našla, skliče skupaj svoje prijateljice in svoje sosede, rekoč: ›Veselite se z menoj, kajti našla sem košček, ki sem ga izgubila.‹',
        10: 'Povem vam, enaka radost je v prisotnosti Božjih angelov nad enim grešnikom, ki se pokesa.«',
        11: 'In rekel je: »Neki človek je imel dva sina',
        12: 'in mlajši izmed njiju je rekel svojemu očetu: ›Oče, daj mi moj delež dobrin, ki mi pripadajo.‹ In razdelil jima je svoja sredstva za preživljanje.',
        13: 'Ne veliko dni kasneje pa je mlajši sin zbral vse skupaj in šel na pot v daljno deželo in tam z razuzdanim življenjem potrošil svoje imetje.',
        14: 'Ko pa je vse zapravil, je v tej deželi nastala silna lakota in začel je živeti v pomanjkanju.',
        15: 'In odšel je ter se pridružil meščanu te dežele, ta pa ga je poslal na svoja polja, da pase svinje.',
        16: 'Svoj trebuh pa si je želel napolniti z luščinami, ki so jih jedle svinje, pa mu [jih] nihče ni dal.',
        17: '§ Ko pa je prišel k sebi, je rekel: ›Koliko najetih služabnikov mojega očeta ima kruha na pretek, jaz pa umiram od lakote!',
        18: 'Vstal bom ter odšel k svojemu očetu in mu bom rekel: ›Oče, grešil sem zoper nebo in pred teboj',
        19: 'in nisem več vreden, da bi se imenoval tvoj sin. Naredi me kakor enega svojih najetih služabnikov.‹‹',
        20: 'In vstal je ter prišel k svojemu očetu. Toda ko je bil še daleč, ga je njegov oče zagledal ter imel sočutje in pritekel ter se oklenil njegovega vratu in ga poljubil.',
        21: 'Sin pa mu je rekel: ›Oče, grešil sem zoper nebo in v tvojih očeh in nisem več vreden, da bi se imenoval tvoj sin.‹',
        22: 'Toda oče je svojim služabnikom rekel: ›Prinesite najboljše svečano oblačilo in ga nadenite nanj in na njegovo roko dajte prstan ter čevlje na njegova stopala',
        23: 'in privedite sèm pitano tele in ga zakoljite in jejmo ter bodimo veseli,',
        24: 'kajti ta moj sin je bil mrtev, pa je ponovno živ; bil je izgubljen, pa je najden.‹ In začeli so se veseliti.',
        25: 'Torej njegov starejši sin je bil na polju. Ko pa je prišel ter se bližal hiši, je zaslišal glasbo in ples.',
        26: 'In poklical je enega izmed služabnikov in vprašal, kaj pomenijo te stvari.',
        27: 'In ta mu je rekel: ›Tvoj brat je prišel in tvoj oče je zaklal pitano tele, ker ga je prejel živega in zdravega.‹',
        28: 'In bil je jezen in ni hotel vstopiti, zato je njegov oče prišel ven ter ga povabil.',
        29: 'In odgovoril je in rekel svojemu očetu: ›Glej! Ta mnoga leta ti služim niti nisem kadarkoli prestopil tvoje zapovedi, pa mi vendarle še nikoli nisi dal kozlička, da bi se s svojimi prijatelji lahko poveselil,',
        30: 'toda takoj, ko je prišel ta tvoj sin, ki je z vlačugami požrl tvoja sredstva za preživljanje, si zanj zaklal pitano tele.‹',
        31: 'On pa mu je rekel: ›Sin, ti si vedno z menoj in vse, kar imam, je tvoje.',
        32: 'Primerno je bilo, da bi se poveselili in bili veseli, kajti ta tvoj brat je bil mrtev, pa je ponovno živ; in bil je izgubljen, pa je najden.‹«',
    },
    16: {
        1: 'Svojim učencem pa je prav tako rekel: »Bil je nek bogataš, ki je imel oskrbnika in ta isti mu je bil zatožen, da je zapravljal njegove dobrine.',
        2: 'In poklical ga je ter mu rekel: ›Kako to, da to slišim o tebi? Daj mi obračun svojega oskrbništva, kajti ne boš več mogel biti oskrbnik.‹',
        3: 'Potem je oskrbnik sam pri sebi rekel: ›Kaj naj storim? Kajti moj gospodar od mene jemlje oskrbništvo; kopáti ne morem, prositi me je sram.',
        4: 'Odločil sem se kaj storiti, da me bodo lahko sprejeli v svoje hiše, ko bom odstavljen od oskrbništva.‹',
        5: 'Tako je k sebi poklical vsakega izmed dolžnikov svojega gospodarja in rekel prvemu: ›Koliko dolguješ mojemu gospodarju?‹',
        6: 'In ta je rekel: ›Sto meric olja.‹ Rekel mu je: ›Vzemi svojo zadolžnico in hitro sedi ter zapiši petdeset.‹',
        7: 'Potem je rekel drugemu: ›In koliko dolguješ ti?‹ In ta je rekel: ›Sto meric pšenice.‹ In rekel mu je: ›Vzemi svojo zadolžnico in zapiši osemdeset.‹',
        8: 'In gospodar je pohvalil nepravičnega oskrbnika, ker je modro ravnal, kajti otroci tega sveta so v svojem rodu modrejši od otrok svetlobe.',
        9: 'In pravim vam: ›Prijatelje si pridobivajte s krivičnim mamonom, da vas, ko padete, lahko sprejmejo v večna prebivališča.‹',
        10: 'Kdor je zvest v tem, kar je najmanjše, je zvest tudi v velikem; kdor pa je nepravičen v najmanjšem, je nepravičen tudi v velikem.',
        11: 'Če torej niste bili zvesti s krivičnim mamonom, kdo bo vašemu zaupanju poveril resnična bogastva?',
        12: 'In če niste bili zvesti s tem, kar je od drugih ljudi, kdo vam bo dal to, kar je vaše?',
        13: 'Noben služabnik ne more služiti dvema gospodarjema, ker ali bo enega sovražil in drugega ljubil, ali pa se bo držal k enemu in preziral drugega. Ne morete služiti Bogu in mamonu.«',
        14: 'In tudi farizeji, ki so bili lakomni, so slišali vse te stvari in ga zasmehovali.',
        15: 'Rekel jim je: »Vi ste tisti, ki sebe opravičujete pred ljudmi, toda Bog pozna vaša srca, kajti to, kar je zelo cenjeno med ljudmi, je v Božjih očeh ogabnost.',
        16: 'Postava in preroki so bili do Janeza. Od tedaj se oznanja Božje kraljestvo in vsak pritiska vanj.',
        17: 'Lažje pa je za nebo in zemljo, da preideta, kakor da manjka ena pičica postave.',
        18: 'Kdorkoli odslovi svojo ženo in poroči drugo, zagreši zakonolomstvo, in kdorkoli poroči njo, ki jo je njen soprog odslovil, zagreši zakonolomstvo.',
        19: 'Bil je nek bogataš, ki je bil oblečen v škrlat in tanko laneno platno in vsak dan razkošno jedel in pil',
        20: 'in bil je nek berač, po imenu Lazar, ki je bil poln vnetij položen pred njegova velika vrata',
        21: 'in želel je biti nahranjen z drobtinami, ki so padale z bogataševe mize; poleg tega so prišli psi in lizali njegova vnetja.',
        22: 'Pripetilo pa se je, da je berač umrl in angeli so ga odnesli v Abrahamovo naročje, in tudi bogataš je umrl ter bil pokopan',
        23: '§ in v peklu je povzdignil svoje oči, medtem ko je bil mučen in daleč stran zagledal Abrahama in Lazarja v njegovem naročju.',
        24: 'In zaklical je ter rekel: ›Oče Abraham, usmili se me in pošlji Lazarja, da bi lahko konico svojega prsta pomočil v vodo in ohladil moj jezik, kajti mučen sem v tem plamenu.‹',
        25: 'Toda Abraham je rekel: ›Sin, spomni se, da si v svojem življenju prejemal svoje dobre stvari in prav tako Lazar zle stvari; toda on je sedaj potolažen, ti pa si mučen.',
        26: 'Poleg vsega tega pa je med nami in teboj velik, nespremenljiv prepad, tako da tisti, ki bi hoteli prečkati od tod k vam, ne morejo niti oni ne morejo prečkati k nam, da bi prišli od tam.‹',
        27: 'Potem je rekel: ›Prosim te torej oče, da ga pošlješ k hiši mojega očeta,',
        28: 'kajti pet bratov imam, da jim bo lahko pričeval, da ne bi tudi oni prišli v ta kraj mučenja.‹',
        29: 'Abraham mu reče: ›Imajo Mojzesa in preroke, naj njih poslušajo.‹',
        30: 'Ta pa je rekel: ›Ne, oče Abraham, toda če gre k njim kdo od mrtvih, se bodo pokesali.‹',
        31: 'On pa mu je rekel: ›Če ne poslušajo ne Mojzesa in ne prerokov, ne bodo pregovorjeni, četudi nekdo vstane od mrtvih.‹«',
    },
    17: {
        1: 'Potem je rekel učencem: »Ni mogoče, da prestopki ne bi prišli, toda gorje tistemu, po katerem bodo prišli!',
        2: 'Bolje bi bilo zanj, da bi bil mlinski kamen obešen okoli njegovega vratu, on sam pa vržen v morje, kakor da bi pohujšal enega od teh malčkov.',
        3: 'Pazite se: ›Če se tvoj brat prekrši zoper tebe, ga oštej; če pa se pokesa, mu odpusti.',
        4: 'In če se sedemkrat dnevno prekrši zoper tebe in se sedemkrat dnevno ponovno obrne k tebi, rekoč: ›Kesam se,‹ mu boš odpustil.‹«',
        5: 'In apostoli so rekli Gospodu: »Povečaj našo vero.«',
        6: 'Gospod pa je rekel: »Če bi imeli vero kakor zrno gorčičnega semena, bi lahko rekli temu drevesu črne murve: ›Bodi izruvana s korenino in bodi posajena v morje‹ in bi vam bila pokorna.',
        7: 'Toda kdo izmed vas, ki ima služabnika, ki orje ali pase živino, mu bo v kratkem, ko pride iz polja, rekel: ›Pojdi in sedi k obedu?‹',
        8: 'In ali mu ne bo raje rekel: ›Pripravi mi nekaj, da bom lahko večerjal in se opaši ter mi strezi, dokler se ne najem in napijem, potem pa boš ti jedel in pil?‹',
        9: 'Mar se bo zahvalil temu služabniku, ker je storil stvari, ki so mu bile ukazane? Menim, da ne.',
        10: 'Tako tudi vi, ko boste naredili vse te stvari, ki so vam ukazane, recite: ›Nekoristni služabniki smo. Naredili smo to, kar je bila naša dolžnost, da storimo.‹«',
        11: 'In pripetilo se je, ko je šel v Jeruzalem, da je šel čez sredo Samarije in Galileje.',
        12: 'In ko je vstopil v neko vas, ga je tam srečalo deset mož, ki so bili gobavi, ki so stali daleč stran',
        13: 'in povzdignili so svoje glasove ter rekli: »Jezus, Učitelj, usmili se nas.«',
        14: 'In ko jih je zagledal, jim je rekel: »Pojdite, pokažite se duhovnikom.« In pripetilo se je, da ko so šli, so bili očiščeni.',
        15: 'In ko je eden izmed njih videl, da je bil ozdravljen, se je obrnil nazaj in z močnim glasom slavil Boga',
        16: 'in pri njegovih stopalih je padel dol na svoj obraz in mu dal zahvalo; in ta je bil Samarijan.',
        17: 'In Jezus odgovori ter reče: »Mar ni bilo tu deset očiščenih? Toda kje je onih devet?',
        18: 'Nikogar ni najti, ki bi se vrnil, da izroči slavo Bogu, razen tega tujca.«',
        19: '§ In rekel mu je: »Vstani, pojdi svojo pot, tvoja vera te je naredila zdravega.«',
        20: 'In ko so ga farizeji povprašali, kdaj naj bi prišlo Božje kraljestvo, jim je odgovoril in rekel: »Božje kraljestvo ne prihaja z opazovanjem,',
        21: '§ tudi ne bodo rekli: ›Glejte, tukaj!‹ ali: ›Glejte tam!‹ kajti glejte, Božje kraljestvo je znotraj vas.«',
        22: 'Učencem pa je rekel: »Prišli bodo dnevi, ko boste želeli videti enega izmed dni Sina človekovega, pa ga ne boste videli.',
        23: 'In govorili vam bodo: ›Glejte tukaj‹ ali: ›Glejte tam.‹ Ne hodite za njimi niti jim ne sledite.',
        24: 'Kajti kakor bliskanje, ki zasveti iz enega konca pod nebom, sveti do drugega konca pod nebom, tako bo tudi Sin človekov na svoj dan.',
        25: 'Toda najprej mora pretrpeti mnoge stvari in biti zavržen od tega rodu.',
        26: 'In kakor je bilo v Noetovih dneh, takó bo tudi v dneh Sina človekovega.',
        27: 'Jedli so, pili, poročali so žene, dane so bile v zakon, vse do dne, ko je Noe vstopil v barko in je prišla poplava ter jih vse uničila.',
        28: 'Podobno bo, kot je bilo v Lotovih dneh; jedli so, pili, kupovali, prodajali, sadili, zidali;',
        29: 'toda istega dne, ko je Lot odšel iz Sódome, sta z neba deževala ogenj in žveplo ter jih vse uničila.',
        30: 'Točno takó bo na dan, ko se razodene Sin človekov.',
        31: 'Na tisti dan naj tisti, ki bo na hišni strehi in njegove stvari v hiši, ne pride dol, da jih vzame proč; in kdor je na polju, naj se prav tako ne vrača nazaj.',
        32: 'Spomnite se Lotove žene.',
        33: 'Kdorkoli si bo prizadeval rešiti svoje življenje, ga bo izgubil; kdorkoli pa bo izgubil svoje življenje, ga bo ohranil.',
        34: 'Povem vam, v tej noči bosta dva človeka na eni postelji; eden bo vzet, drugi pa puščen.',
        35: 'Dve ženski bosta skupaj mleli; ena bo vzeta, druga pa puščena.',
        36: '§ Dva moža bosta na polju; eden bo vzet, drugi pa puščen.«',
        37: 'In odgovorili so mu ter rekli: »Kje, Gospod?« In on jim je rekel: »Kjerkoli je telo, tam bodo orli zbrani skupaj.«',
    },
    18: {
        1: 'In povedal jim je priliko zato, da morajo ljudje vedno moliti in ne izgubiti poguma,',
        2: 'rekoč: »V mestu je bil sodnik, ki se ni bal Boga niti se ni oziral na človeka.',
        3: 'In v tistem mestu je bila vdova in prišla je k njemu, rekoč: ›Maščuj me pred mojim nasprotnikom.‹',
        4: 'On pa nekaj časa ni hotel, toda kasneje si je sam pri sebi rekel: ›Čeprav se ne bojim Boga niti se ne oziram na človeka,',
        5: 'vendarle, ker me ta vdova nadleguje, ji bom izvršil pravico, da me s svojim nenehnim prihajanjem ne bi izmučila.‹«',
        6: 'Gospod pa je rekel: »Poslušajte, kaj pravi nepravični sodnik.',
        7: 'In ali ne bo Bog maščeval svojih lastnih izvoljenih, ki dan in noč vpijejo k njemu, čeprav jih dolgo prenaša?',
        8: 'Povem vam, da jih bo naglo maščeval. Vendar ko pride Sin človekov, ali bo našel vero na zemlji?«',
        9: 'Nekaterim pa, ki so zaupali sami vase, da so bili pravični in so prezirali druge, je povedal to prispodobo:',
        10: '»Dva človeka sta šla gor v tempelj molit: en farizej, drugi pa davkar.',
        11: 'Farizej je stal in sam s seboj takole molil: ›Bog, zahvaljujem se ti, ker nisem kakor so drugi ljudje, izsiljevalci, nepravični, zakonolomci ali celó kakor ta davkar.',
        12: 'Postim se dvakrat tedensko, desetine dajem od vsega, kar imam.',
        13: 'Davkar pa, ki je stal daleč stran, ni hotel niti svojih oči povzdigniti k nebu, temveč se je udarjal po svojih prsih, rekoč: ›Bog bodi usmiljen meni grešniku.‹',
        14: 'Povem vam, ta človek je odšel dol k svoji hiši toliko bolj opravičen kakor drugi, kajti vsak, kdor sebe povišuje, bo ponižan; kdor pa sebe ponižuje, bo povišan.«',
        15: 'K njemu pa so privedli tudi otročiče, da bi se jih dotaknil, toda ko so njegovi učenci to videli, so jih ošteli.',
        16: 'Toda Jezus jih je poklical k sebi in rekel: »Dovolite majhnim otrokom prihajati k meni in ne prepovejte jim, kajti takšnih je Božje kraljestvo.',
        17: 'Resnično, povem vam: ›Kdorkoli ne bo sprejel Božjega kraljestva kakor majhen otrok, nikakor ne bo vstopil vanj.‹«',
        18: 'In nek vladar ga je vprašal, rekoč: »Dobri Učitelj, kaj naj storim, da bom podedoval večno življenje?«',
        19: 'Jezus pa mu je rekel: »Zakaj me kličeš dober? Nihče ni dober, razen enega, to je Boga.',
        20: 'Zapovedi poznaš: ›Ne zagreši zakonolomstva,‹ ›Ne ubijaj,‹ ›Ne kradi,‹ ›Ne pričaj po krivem,‹ ›Spoštuj svojega očeta in svojo mater.‹«',
        21: 'On pa je rekel: »Vsega tega sem se držal od svoje mladosti dalje.«',
        22: 'Torej ko je Jezus slišal te besede, mu je rekel: »Vendarle ti manjka ena stvar. Prodaj vse, kar imaš in razdeli revnim in imel boš zaklad v nebesih in pridi, hodi za menoj.«',
        23: 'In ko je oni to slišal, je bil zelo žalosten, kajti bil je zelo bogat.',
        24: 'In ko je Jezus videl, da je bil zelo žalosten, je rekel: »Kako težko bodo tisti, ki imajo bogastva, vstopili v Božje kraljestvo!',
        25: 'Kajti lažje je za kamelo, da gre skozi šivankino uho, kakor za bogataša vstopiti v Božje kraljestvo.«',
        26: 'Tisti pa, ki so to slišali, so rekli: »Kdo je potem lahko rešen?«',
        27: 'In rekel je: »Stvari, ki so nemogoče z ljudmi, so mogoče z Bogom.«',
        28: 'Potem je Peter rekel: »Glej! Vse smo zapustili in ti sledili.«',
        29: 'In rekel jim je: »Resnično, povem vam: ›Ni človeka, ki je zapustil hišo ali starše ali brate ali ženo ali otroke zaradi Božjega kraljestva,',
        30: 'ki ne bo prejel mnogokrat več v tem sedanjem času in večno življenje v svetu, ki pride.‹«',
        31: 'Potem je k sebi vzel dvanajstere in jim rekel: »Glejte, mi gremo gor v Jeruzalem in vse besede, ki so glede Sina človekovega napisane po prerokih, se bodo dovršile.',
        32: 'Kajti izročen bo poganom in bo zasmehovan in hudobno tretiran ter opljuvan,',
        33: 'pa tudi bičali ga bodo in usmrtili in tretji dan bo ponovno vstal.«',
        34: 'Oni pa niso razumeli nobene od teh besed in ta govor je bil skrit pred njimi niti niso razumeli besed, ki so bile izgovorjene.',
        35: 'In pripetilo se je, da ko je prišel blizu Jerihe, da je ob poti sedèl nek slepi mož ter beračil.',
        36: 'In ko je slišal iti mimo množico, je vprašal, kaj je to pomenilo.',
        37: 'In povedali so mu, da gre mimo Jezus Nazarečan.',
        38: 'In ta je zavpil, rekoč: »Jezus, ti Davidov Sin, usmili se me.«',
        39: 'Tisti pa, ki so hodili spredaj, so ga ošteli, da naj molči, toda on je bolj in bolj vpil: » Ti, Davidov Sin, usmili se me.«',
        40: 'In Jezus se je ustavil ter ukazal, naj bo priveden k njemu in ko je ta prišel bliže, ga je vprašal,',
        41: 'rekoč: »Kaj hočeš, da naj ti storim?« On pa je rekel: »Gospod, da lahko prejmem svoj vid.«',
        42: 'Jezus mu je rekel: »Prejmi svoj vid, tvoja vera te je rešila.«',
        43: 'In takoj je prejel svoj vid in mu sledil ter proslavljal Boga. In ko so vsi ljudje to videli, so dali hvalo Bogu.',
    },
    19: {
        1: 'In Jezus je vstopil [v Jeriho] in šel skozi Jeriho.',
        2: 'In glej, tam je bil mož, imenovan Zahej, ki je bil šef med davkarji in je bil bogat.',
        3: 'In prizadeval si je, da bi videl, kdo je bil Jezus, pa ni mogel zaradi množice, ker je bil majhne postave.',
        4: 'In stekel je naprej ter splezal na egiptovsko smokvo, da bi ga videl, kajti moral bi iti mimo po tej poti.',
        5: 'Ko je Jezus prišel na ta kraj, je pogledal gor, ga zagledal in mu rekel: »Zahej, podvizaj se in pridi dol, kajti danes moram ostati v tvoji hiši.«',
        6: 'In ta je pohitel in prišel dol ter ga radostno sprejel.',
        7: 'In ko so to videli, so vsi godrnjali, rekoč: »Ta je odšel, da bi bil gost pri človeku, ki je grešnik.«',
        8: 'Zahej pa je vstal in rekel Gospodu: »Glej, Gospod, polovico svojih dobrin dam revnim in če sem po krivem obtožen, da sem karkoli vzel od kateregakoli človeka, mu štirikratno povrnem.«',
        9: 'Jezus pa mu je rekel: »Ta dan je prišla k tej hiši rešitev duše, glede na to, da je tudi on Abrahamov sin.',
        10: 'Kajti Sin človekov je prišel, da poišče in da reši to, kar je bilo izgubljeno.«',
        11: 'In medtem ko so slišali te stvari, je dodal in povedal prispodobo, kajti bil je blizu Jeruzalema in ker so mislili, da naj bi se Božje kraljestvo prikazalo takoj.',
        12: 'Rekel je torej: »Neki visoki plemič je odšel v daljno deželo, da prejme zase kraljestvo in da se vrne.',
        13: '§ In poklical je svojih deset služabnikov ter jim razdelil deset funtov in jim rekel: ›Zaposlite se s trgovanjem, dokler ne pridem.‹',
        14: 'Toda njegovi državljani so ga sovražili in za njim poslali sporočilo, rekoč: ›Nočemo, da bi ta človek zavladal nad nami.‹',
        15: 'Pripetilo pa se je, ko se je vrnil, da je prejel kraljestvo. Potem je ukazal, naj te služabnike, ki jim je dal denar, pokličejo k njemu, da lahko izve, koliko je vsak človek pridobil s trgovanjem.',
        16: 'Potem je prišel prvi, rekoč: ›Gospodar, tvoj funt je pridobil deset funtov.‹',
        17: 'Rekel mu je: ›V redu, ti dobri služabnik, ker si bil zvest v zelo majhnem, imej oblast nad desetimi mesti.‹',
        18: 'In prišel je drugi, rekoč: ›Gospod, tvoj funt je pridobil pet funtov.‹',
        19: 'In tudi njemu je rekel podobno: ›Tudi ti bodi nad petimi mesti.‹',
        20: 'In prišel je še en, rekoč: ›Gospod, glej, tukaj je tvoj funt, ki sem ga hranil v prtiču,',
        21: 'kajti bal sem se te, ker si strog človek; jemlješ to, česar nisi položil in žanješ to, česar nisi posejal.‹',
        22: 'On pa mu reče: ›Po tvojih lastnih ustih te bom sodil, ti zlobni služabnik. Vedel si, da sem bil strog človek, ki jemljem to, česar nisem položil in žanjem to, česar nisem posejal.',
        23: 'Zakaj torej mojega denarja nisi dal v banko, da bi lahko ob svojem prihodu svojo lastnino zahteval z obrestmi?‹',
        24: 'In rekel je tem, ki so stali poleg: ›Vzemite od njega funt in ga dajte tistemu, ki ima deset funtov.‹',
        25: '(Oni pa so mu rekli: ›Gospod, ta ima deset funtov.‹)',
        26: 'Kajti povem vam: ›Da se bo vsakemu, ki ima, dalo; od tistega, ki nima, pa se bo odvzelo celó to, kar ima.‹',
        27: 'Toda tiste moje sovražnike, ki niso hoteli, da bi jim jaz vladal, privedite sèm in jih pokončajte pred menoj.‹«',
        28: 'In ko je tako govoril, je šel pred njimi ter se vzpenjal v Jeruzalem.',
        29: 'Pripetilo pa se je, ko je prišel blizu Bétfage in Betanije, pri gori, ki se imenuje Oljska gora, [da] je poslal dva izmed svojih učencev,',
        30: 'rekoč: »Pojdita v vas nasproti vama, v kateri bosta ob svojem vstopu našla privezano žrebe, na katerem človek še nikoli ni sedel. Odvežita ga in ga privedita sèm.',
        31: 'Če pa vaju katerikoli človek vpraša: ›Zakaj ga odvezujeta?‹ mu recita takole: ›Ker ga potrebuje Gospod.‹«',
        32: 'In onadva, ki sta bila poslana, sta šla svojo pot in našla tako, kakor jima je povedal.',
        33: 'In ko sta odvezovala žrebe, so jima lastniki le-tega rekli: »Zakaj odvezujeta žrebe?«',
        34: 'Onadva pa sta rekla: »Gospod ga potrebuje.«',
        35: 'In privedla sta ga k Jezusu in svoje obleke vrgla na žrebe ter nanj posadila Jezusa.',
        36: 'In ko je šel, so na pot razgrinjali svoja oblačila.',
        37: 'Ko je prišel blizu, torej celó k pobočju Oljske gore, se je celotna množica učencev začela veseliti in z močnim glasom hvaliti Boga za vsa mogočna dela, ki so jih videli,',
        38: 'rekoč: »Blagoslovljen naj bo Kralj, ki prihaja v imenu Gospodovem. V nebesih mir in slava na višavah.«',
        39: 'Nekaj farizejev izmed množice pa mu je reklo: »Učitelj, oštej svoje učence.«',
        40: 'In odgovoril jim je in jim rekel: »Povem vam, da če bi ti molčali, bodo takoj kamni zavpili.«',
        41: 'Ko pa je prišel bliže, je zagledal mesto ter se razjokal nad njim,',
        42: 'rekoč: »Če bi ti spoznalo, celó ti, vsaj na ta tvoj dan, stvari, ki pripadajo tvojemu miru! Toda sedaj so skrite pred tvojimi očmi.',
        43: 'Kajti nadte bodo prišli dnevi, ko bodo tvoji sovražniki okoli tebe nasuli okope in te obkolili in te stiskali na vsaki strani',
        44: 'in zravnali te bodo z zemljo in tvoje otroke v tebi; in v tebi ne bodo pustili enega kamna na drugem, ker nisi spoznalo časa svojega obiskanja.«',
        45: '§ In odšel je v tempelj ter začel izganjati te, ki so v njem prodajali in te, ki so kupovali,',
        46: 'rekoč jim: »Pisano je: ›Moja hiša je hiša molitve,‹ toda vi ste jo naredili za brlog razbojnikov.«',
        47: 'In vsak dan je učil v templju. Toda visoki duhovniki in pisarji in vodje ljudstva so si prizadevali, da ga pokončajo,',
        48: 'pa niso mogli najti, kaj bi lahko storili, kajti vsi ljudje so ga zelo pozorno poslušali.',
    },
    20: {
        1: 'In pripetilo se je, da so na enega izmed tistih dni, ko je v templju učil ljudi in oznanjal evangelij, prišli nad njega visoki duhovniki in pisarji s starešinami',
        2: 'in mu spregovorili, rekoč: »Povej nam, s kakšno oblastjo delaš te stvari? Ali kdo je tisti, ki ti je dal to oblast?«',
        3: 'In odgovoril je ter jim rekel: »Tudi jaz vas bom vprašal eno besedo in odgovorite mi:',
        4: '›Ali je bil Janezov krst iz nebes ali od ljudi?‹«',
        5: 'Oni pa so razpravljali med seboj, rekoč: »Če bomo rekli: ›Iz nebes,‹ bo rekel: ›Zakaj mu potem niste verjeli?‹',
        6: 'Toda če rečemo: ›Od ljudi,‹ nas bodo vsi ljudje kamnali, kajti pregovorjeni so, da je bil Janez prerok.«',
        7: 'In odgovorili so, da ne morejo povedati, od kod je bil.',
        8: 'In Jezus jim je rekel: »Niti vam jaz ne povem, s kakšno oblastjo delam te stvari.«',
        9: 'Potem je začel ljudem govoriti to prispodobo: »Neki človek je zasadil vinograd in ga prepustil poljedelcem ter za dolgo časa odšel v daljno deželo.',
        10: 'Ob primernem obdobju pa je poslal k poljedelcem služabnika, da bi mu lahko dali od sadu vinograda, toda poljedelci so ga pretepli in ga odposlali praznega.',
        11: 'On pa je ponovno poslal drugega služabnika in tudi njega so pretepli in sramotno ravnali z njim ter ga odposlali praznega.',
        12: 'Pa je ponovno poslal tretjega in tudi njega so ranili ter ga vrgli ven.',
        13: 'Potem je gospodar vinograda rekel: ›Kaj naj storim? Poslal bom svojega ljubljenega sina. Ko ga bodo videli, ga bodo mogoče spoštovali.‹',
        14: 'Toda ko so ga poljedelci zagledali, so med seboj razpravljali, rekoč: ›Ta je dedič. Pridite, ubijmo ga, da bo dediščina lahko naša.‹',
        15: 'Tako so ga vrgli iz vinograda in ga ubili. Kaj jim bo torej storil gospodar vinograda?',
        16: 'Prišel bo in uničil te poljedelce, vinograd pa bo dal drugim.« Ko pa so to slišali, so rekli: »Bog ne daj.«',
        17: 'On pa jih je pogledal in rekel: »Kaj je torej to, kar je pisano: ›Kamen, ki so ga graditelji zavrgli, ta isti je postal glava vogalu?‹',
        18: 'Kdorkoli bo padel na ta kamen, bo razbit, toda na kogarkoli bo ta padel, ga bo zmlel v prah.‹«',
        19: 'In visoki duhovniki ter pisarji so skušali to isto uro položiti roke nanj; bali pa so se ljudi, kajti zaznali so, da je to prispodobo govoril proti njim.',
        20: 'In opazovali so ga ter poslali oglednike, ki naj bi se hlinili [za] pravične može, da bi ga lahko prijeli za njegove besede, da bi ga tako lahko izročili voditeljevi moči in oblasti.',
        21: 'In vprašali so ga, rekoč: »Učitelj, vemo, da prav govoriš in učiš niti ne sprejemaš zunanjega videza kogarkoli, temveč resnično učiš Božjo pot:',
        22: '›Ali je za nas zakonito, da dajemo cesarju davek ali ne?‹«',
        23: 'Vendar je zaznal njihovo prebrisanost in jim rekel: »Zakaj me skušate?',
        24: 'Pokažite mi kovanec. Čigavo podobo in napis ima?« Odgovorili so in rekli: »Cesarjevo.«',
        25: 'In rekel jim je: »Povrnite torej cesarju stvari, ki so cesarjeve, Bogu pa stvari, ki so Božje.«',
        26: 'In pred ljudmi ga niso mogli prijeti zaradi njegovih besed in čudili so se ob njegovem odgovoru in molčali.',
        27: 'Potem so prišli k njemu nekateri izmed saducejev, ki zanikajo, da obstaja kakršnokoli vstajenje in vprašali so ga,',
        28: 'rekoč: »Učitelj, Mojzes nam je napisal: ›Če komu umre brat, ki ima ženo in umre brez otrok, da naj njegov brat vzame njegovo ženo in svojemu bratu obudi seme.',
        29: 'Bilo je torej sedem bratov in prvi je vzel ženo ter umrl brez otrok.',
        30: '§ In drugi jo je vzel za ženo ter umrl brez otrok.',
        31: 'In vzel jo je tretji in na podoben način tudi sedmi, pa niso zapustili otrok in so umrli.',
        32: 'Zadnja izmed vseh je umrla tudi ženska.',
        33: 'Čigava žena od teh bo torej ob vstajenju? Kajti sedem jo je imelo za ženo.‹«',
        34: 'Jezus jim odgovori in reče: »Otroci tega sveta se poročajo in so dane v zakon,',
        35: 'toda tisti, ki bodo šteti za vredne, da dosežejo oni svet in vstajenje od mrtvih, se ne bodo niti poročali, niti ne bodo dane v zakon,',
        36: 'niti ne morejo več umreti, kajti enaki so angelom in so Božji otroci, saj so otroci vstajenja.',
        37: 'Torej, da so mrtvi obujeni, je pokazal celó Mojzes pri grmu, ko je imenoval Gospoda ›Bog Abrahamov in Bog Izakov in Bog Jakobov.‹',
        38: 'Kajti on ni Bog mrtvih, temveč živih, kajti njemu vsi živijo.«',
        39: 'Tedaj so nekateri izmed pisarjev odgovorili in rekli: »Učitelj, dobro si povedal.«',
        40: 'Nató pa se ga niso drznili vprašati nobenega vprašanja več.',
        41: 'In rekel jim je: »Kako pravijo, da je Kristus Davidov sin?',
        42: 'In sam David pravi v knjigi Psalmov: › Gospod je rekel mojemu Gospodu: ›Sedi na mojo desnico,',
        43: 'dokler ne naredim tvojih sovražnikov [za] tvojo pručko.‹‹',
        44: 'David mu torej reče Gospod, kako je potem on njegov sin?«',
        45: 'Potem je pred občinstvom vseh ljudi svojim učencem rekel:',
        46: '»Pazite se pisarjev, ki želijo hoditi v dolgih svečanih oblačilih in imajo radi pozdrave na trgih in najvišje sedeže v sinagogah ter vodilna mesta na praznovanjih,',
        47: 'ki vdovam požirajo hiše in zaradi lepšega delajo dolge molitve; isti bodo prejeli večje prekletstvo.«',
    },
    21: {
        1: 'In pogledal je navzgor in videl bogataše metati svoje darove v zakladnico.',
        2: 'Videl pa je tudi neko siromašno vdovo vreči vanjo dva kovanca.',
        3: 'In rekel je: »Resnično, jaz vam pravim, da je ta siromašna vdova vrgla vanjo več kot vsi,',
        4: 'kajti vsi ti so iz svojega obilja vrgli vanjo daritve Bogu, toda ona je iz svojega uboštva vrgla vanjo vsa sredstva za preživljanje, ki jih je imela.«',
        5: 'In ko so nekateri govorili o templju, kako je okrašen z lepimi kamni in darovi, je rekel:',
        6: '» Glede teh stvari, ki jih gledate, pa bodo prišli dnevi, v katerih ne bo ostal en kamen na drugem, ki ne bi bil zrušen.«',
        7: 'In vprašali so ga, rekoč: »Učitelj, toda kdaj bodo te stvari? In kakšno znamenje se bo zgodilo, ko se bodo te stvari pripetile?«',
        8: 'In rekel je: »Pazite, da ne boste zavedeni, kajti mnogi bodo prišli v mojem imenu, rekoč: ›Jaz sem Kristus in čas se je približal;‹ ne pojdite torej za njimi.',
        9: 'Toda ko boste slišali o vojnah in vstajah, ne bodite prestrašeni, kajti te stvari se morajo najprej zgoditi, toda konec še ni v kratkem.«',
        10: 'Tedaj jim je rekel: »Narod bo vstal zoper narod in kraljestvo zoper kraljestvo',
        11: 'in veliki potresi bodo na raznih krajih in lakote ter kužne bolezni in strašni prizori ter velika znamenja se bodo zgodila z neba.',
        12: 'Toda pred vsem tem bodo nad vas iztegovali svoje roke in vas preganjali ter vas izročali v shodnice in ječe [in] zaradi mojega imena boste privedeni pred kralje in vladarje.',
        13: 'To pa se bo obrnilo k vam za pričevanje.',
        14: 'Pomirite se torej v svojih srcih, da ne boste prej premišljevali, kaj boste odgovorili,',
        15: 'kajti jaz vam bom dal usta in modrost, kateri vsi vaši nasprotniki ne bodo mogli ugovarjati niti se ji upirati.',
        16: 'Izdajali pa vas bodo tako starši kakor bratje, žlahta in prijatelji in nekaterim izmed vas bodo povzročili, da boste usmrčeni.',
        17: 'In vsi ljudje vas bodo sovražili zaradi mojega imena.',
        18: 'Toda niti las z vaše glave ne bo propadel.',
        19: '§ S svojim potrpljenjem si pridobivate svoje duše.',
        20: 'In ko boste videli Jeruzalem obdan z vojskami, tedaj vedite, da je blizu opustošenje le-tega.',
        21: 'Potem naj tisti, ki so v Judeji, pobegnejo v gore; in naj tisti, ki so v njegovi sredi, odidejo ven; in naj tisti, ki so na podeželju, ne vstopijo vanj.',
        22: 'Kajti to so dnevi maščevanja, da se bodo lahko izpolnile vse stvari, ki so napisane.',
        23: 'Toda gorje v tistih dneh tem, ki so z otrokom in tem, ki dojijo! Kajti v deželi bo velika tegoba in bes nad temi ljudmi.',
        24: 'In padali bodo pod ostrino meča in odvedeni bodo v ujetništvo med vse narode in Jeruzalem bodo mendrali pogani, dokler se ne dopolnijo časi poganov.',
        25: 'In znamenja bodo na soncu in na luni in na zvezdah; in nad zemljo tegoba narodov z zmedenostjo; morje in valovi bodo rjoveli;',
        26: 'srca bodo ljudem odpovedovala zaradi strahu in zaradi opazovanja za temi stvarmi, ki prihajajo na zemljo, kajti moči neba se bodo majale.',
        27: 'In tedaj bodo videli Sina človekovega prihajati v oblaku z močjo in veliko slavo.',
        28: 'Ko pa se bodo te stvari začele dogajati, potem poglejte gor in dvignite svoje glave, kajti vaša odkupitev se približuje.«',
        29: 'In spregovoril jim je v prispodobi: »Poglejte figovo drevo in vsa drevesa;',
        30: 'ko sedaj poganjajo, vi vidite in sami veste, da je torej poletje blizu.',
        31: 'Tako tudi vi, ko vidite, da se te stvari dogajajo, védite, da je Božje kraljestvo blizu.',
        32: 'Resnično, povem vam: ›Ta rod ne bo preminil, dokler ne bo vse izpolnjeno.',
        33: 'Nebo in zemlja bosta minila, toda moje besede ne bodo minile.',
        34: 'Pazite pa se, da ne bi bila vaša srca kadarkoli preobremenjena s prenasičenostjo in pijanostjo in skrbmi tega življenja in tako, da ta dan nad vas ne pride nepričakovano.',
        35: 'Kajti kakor zanka bo prišel na vse tiste, ki prebivajo na obličju celotne zemlje.',
        36: 'Čujte torej in nenehno molíte, da boste lahko šteti za vredne, da pobegnete vsem tem stvarem, ki se bodo pripetile in stopite pred Sina človekovega.‹«',
        37: 'In podnevi je učil v templju, ponoči pa je odšel ven ter prebival na gori, ki se imenuje Oljska gora.',
        38: 'In vsi ljudje so prihajali zgodaj zjutraj k njemu v tempelj, da bi ga poslušali.',
    },
    22: {
        1: 'Torej približal se je praznik nekvašenega kruha, ki se imenuje Pasha.',
        2: 'Visoki duhovniki in pisarji pa so si prizadevali, kako bi ga lahko ubili, kajti bali so se ljudi.',
        3: 'Tedaj je Satan vstopil v Juda, z vzdevkom Iškarijot, ki je bil izmed dvanajsterih.',
        4: 'In ta je odšel svojo pot ter se posvetoval z visokimi duhovniki in stotniki, kako bi jim ga lahko izdal.',
        5: 'In ti so bili veseli in se obvezali, da mu dajo denar.',
        6: 'In obljubil je ter iskal priložnost, da jim ga izda v odsotnosti množice.',
        7: 'Potem je prišel dan nekvašenega kruha, ko mora biti zaklano pashalno jagnje.',
        8: 'In poslal je Petra ter Janeza, rekoč: »Pojdita in nam pripravita pashalno jagnje, da bomo lahko jedli.«',
        9: 'In rekla sta mu: »Kje želiš, da ga pripraviva?«',
        10: 'Rekel jima je: »Glejta, ko vstopita v mesto, vaju bo srečal moški, nesoč lončen vrč vode; sledita mu v hišo, v katero vstopa.',
        11: 'Hišnemu očetu pa bosta rekla: ›Učitelj ti pravi: ›Kje je soba za goste, kjer bom s svojimi učenci jedel pashalno jagnje?‹‹',
        12: 'In pokazal vama bo veliko opremljeno zgornjo sobo; tam pripravita.«',
        13: 'In onadva sta odšla ter našla, kakor jima je rekel in pripravila sta pashalno jagnje.',
        14: 'Ko pa je prišla ura, se je usedel in dvanajsteri apostoli z njim.',
        15: 'Rekel jim je: »S hrepenenjem sem si želel, da bi to pashalno jagnje jedel z vami, še predem trpim,',
        16: 'kajti povem vam: ›Ne bom več jedel od tega, dokler to ne bo izpolnjeno v Božjem kraljestvu.‹«',
        17: 'In vzel je čašo ter se zahvalil in rekel: »Vzemite jo in si to razdelite med seboj,',
        18: 'kajti povem vam: ›Ne bom pil od sadu vinske trte, dokler ne pride Božje kraljestvo.‹«',
        19: 'In vzel je kruh in se zahvalil in ga razlomil ter jim dal, rekoč: »To je moje telo, ki je dano za vas, to delajte v spomin name.«',
        20: 'Podobno tudi čašo po večerji, rekoč: »Ta čaša je nova zaveza v moji krvi, ki se preliva za vas.',
        21: 'Toda glejte, roka tistega, ki me izdaja, je z menoj pri mizi.',
        22: 'In Sin človekov resnično gre, kakor je bilo določeno, toda gorje temu človeku, po katerem je izdan!«',
        23: 'In med seboj so se začeli spraševati, kdo izmed njih je bil, da bi storil to stvar.',
        24: 'Med njimi pa je bil tudi prepir, kdo izmed njih naj bi veljal za največjega.',
        25: 'On pa jim je rekel: »Kralji poganov izvajajo gospostvo nad njimi, in kateri izvajajo oblast nad njimi, so imenovani dobrotniki.',
        26: 'Toda vi ne bodite takšni, temveč kdor je med vami največji, naj bo kakor mlajši in kdor je šef kakor tisti, ki streže.',
        27: 'Kajti kdo je večji, kdor sedi pri mizi ali kdor streže? Mar ni, kdor sedi pri mizi? Toda jaz sem med vami kakor tisti, ki streže.',
        28: 'Vi ste tisti, ki ste vztrajali z menoj v mojih skušnjavah.',
        29: 'In določam vam kraljestvo, kakor ga je moj Oče določil meni,',
        30: 'da boste lahko jedli in pili pri moji mizi v mojem kraljestvu in sedeli na prestolih ter sodili dvanajst Izraelovih rodov.«',
        31: 'In Gospod je rekel: »Simon, Simon, glej, Satan je zahlepel, da bi te imel, da te lahko preseje kakor pšenico,',
        32: 'toda jaz sem molil zate, da tvoja vera ne opeša; ko pa boš spreobrnjen, okrépi svoje brate.«',
        33: 'In ta mu je rekel: »Gospod, pripravljen sem iti s teboj, tako v ječo, kakor v smrt.«',
        34: 'On pa je rekel: »Povem ti, Peter, danes petelin ne bo zapel, preden ne boš trikrat zatajil, da me poznaš.«',
        35: 'In rekel jim je: »Ko sem vas poslal brez mošnje in malhe in čevljev ali vam je karkoli manjkalo?« In rekli so: »Nič.«',
        36: 'Potem jim je rekel: »Toda kdor ima mošnjo, naj jo sedaj vzame in prav tako svojo malho; in kdor nima meča, naj proda svojo obleko in enega kupi.',
        37: 'Kajti povem vam, da se mora na meni dovršiti še to, kar je pisano: ›In prištet je bil med prestopnike,‹ kajti stvari glede mene imajo konec.«',
        38: 'In rekli so: »Gospod, glej, tukaj sta dva meča.« On pa jim je rekel: »Dovolj je.«',
        39: 'In prišel je ven ter odšel, kakor je bil navajen, na Oljsko goro in tudi njegovi učenci so mu sledili.',
        40: 'Ko pa je bil na mestu, jim je rekel: »Molíte, da ne vstopite v skušnjavo.«',
        41: 'In od njih je bil oddaljen približno za lučaj kamna ter pokleknil in molil,',
        42: 'rekoč: »Oče, če si voljan, odstrani to čašo od mene, vendar ne moja volja, temveč tvoja naj se zgodi.«',
        43: 'In prikazal se mu je angel iz nebes ter ga krepil.',
        44: '§ Medtem ko je bil v neznosni bolečini, pa je še iskrenejše molil in njegov pot je bil, kakor bi na zemljo padale velike kaplje krvi.',
        45: 'In ko se je dvignil od molitve in prišel k svojim učencem, jih je zaradi bridkosti našel speče',
        46: 'in jim rekel: »Čemu spite? Vstanite in molíte, da ne vstopite v skušnjavo.«',
        47: 'In medtem ko je še govoril, zagleda množico in tisti, ki se je imenoval Juda, eden izmed dvanajsterih, je šel pred njimi in se približal Jezusu, da bi ga poljubil.',
        48: 'Toda Jezus mu je rekel: »Juda, s poljubom izdajaš Sina človekovega?«',
        49: 'Ko so ti, ki so bili okoli njega, videli, kaj bo sledilo, so mu rekli: »Gospod ali naj udarimo z mečem?«',
        50: 'In eden izmed njih je udaril služabnika vélikega duhovnika ter mu odsekal desno uho.',
        51: 'In Jezus je odgovoril ter rekel: »Pustite do tod.« In dotaknil se je njegovega ušesa ter ga ozdravil.',
        52: 'Potem je Jezus rekel visokim duhovnikom in tempeljskim stotnikom ter starešinam, ki so prišli k njemu: »Ali ste prišli ven, kakor proti tatu, z meči in palicami?',
        53: 'Ko sem bil vsak dan z vami v templju, zoper mene niste iztegnili rok, toda to je vaša ura in oblast teme.«',
        54: 'Potem so ga vzeli in ga odvedli ter ga privedli v hišo vélikega duhovnika. Peter pa je sledil od daleč.',
        55: 'In ko so sredi dvorane prižgali ogenj ter skupaj sedli, je Peter sédel mednje.',
        56: 'Toda zagledala ga je neka služkinja, ko je sedel poleg ognja in ga tehtno pogledala ter rekla: »Tudi ta človek je bil z njim.«',
        57: 'On pa ga je zanikal, rekoč: »Ženska, ne poznam ga.«',
        58: 'In malo za tem ga je opazil drug ter rekel: »Tudi ti si izmed njih.« Peter pa je rekel: »Človek, nisem.«',
        59: 'In približno eno uro kasneje je še en prepričano potrdil, rekoč: »Resnično, tudi ta je bil z njim, kajti Galilejec je.«',
        60: 'Peter pa je rekel: »Človek, ne vem kaj praviš.« In takoj, medtem ko je še govoril, je petelin zapel.',
        61: 'Gospod pa se je obrnil in pogledal na Petra. In Peter se je spomnil Gospodove besede, kako mu je rekel: »Preden petelin zapoje, me boš trikrat zatajil.«',
        62: 'In Peter je odšel ven ter se bridko zjokal.',
        63: 'Možje, ki so prijeli Jezusa, so ga zasmehovali in ga udarjali.',
        64: 'In ko so mu zavezali oči, so ga udarili po obrazu in ga vprašali, rekoč: »Prerokuj, kdo je ta, ki te je udaril?«',
        65: 'In mnogo drugih stvari so bogokletno govorili zoper njega.',
        66: 'In takoj, ko je bil dan, so prišli skupaj starešine izmed ljudi, visoki duhovniki ter pisarji in ga odvedli v svoj véliki zbor, rekoč:',
        67: '»Ali si ti Kristus? Povej nam.« On pa jim je rekel: »Če vam povem, ne boste verjeli',
        68: '§ in tudi če vas vprašam, mi ne boste odgovorili niti mi [ne boste] pustili oditi.',
        69: 'Odslej bo Sin človekov sedel na desnici Božje moči.«',
        70: 'Potem so vsi rekli: »Ali si ti potem Božji Sin?« On pa jim je rekel: »Vi pravite, da sem.«',
        71: 'Rekli so: »Kaj potrebujemo kakršnihkoli nadaljnjih prič? Kajti sami smo slišali iz njegovih lastnih ust.«',
    },
    23: {
        1: 'In vsa množica teh je vstala ter ga odvedla k Pilatu.',
        2: 'In začeli so ga obtoževati, rekoč: »Našli smo tega, da izkrivlja narod in prepoveduje dajati cesarju davek, rekoč, da je on sam Kristus Kralj.«',
        3: 'In Pilat ga je vprašal, rekoč: »Ali si ti judovski Kralj?« On pa mu je odgovoril in rekel: »Ti praviš to.«',
        4: 'Potem je Pilat rekel visokim duhovnikom in množici: »Na tem človeku ne najdem nobene krivde.«',
        5: 'Oni pa so bili še bolj kruti, rekoč: »Razvnema ljudi, ko uči po vsej celotni Judeji, začenši v Galileji, do tega mesta.«',
        6: 'Ko je Pilat slišal o Galileji, je vprašal, ali je bil ta človek Galilejec.',
        7: 'Takoj pa, ko je spoznal, da pripada pod Herodovo pristojnost, ga je poslal k Herodu, ki je bil ob tistem času tudi sam v Jeruzalemu.',
        8: 'Ko je Herod zagledal Jezusa, je bil silno vesel, kajti že dlje časa si ga je želel videti, ker je o njem slišal mnoge stvari; in upal je, da bo videl kak čudež, ki ga bo storil.',
        9: 'Potem ga je zasliševal z mnogimi besedami, toda nič mu ni odgovoril.',
        10: 'Poleg pa so stali visoki duhovniki in pisarji ter ga silovito obtoževali.',
        11: 'In Herod ga je s svojimi bojevniki ponižal ter ga zasmehoval in ga oblekel v krasno svečano oblačilo ter ga ponovno poslal k Pilatu.',
        12: 'In tega istega dne sta se Pilat in Herod spoprijateljila, kajti prej sta si bila med seboj sovražna.',
        13: 'Ko pa je Pilat sklical skupaj visoke duhovnike in vladarje ter ljudstvo,',
        14: 'jim je rekel: »Privedli ste mi tega človeka, kot nekoga, ki izkrivlja ljudi in glejte, pred vami sem ga izprašal. Nobene krivde nisem našel na tem človeku glede teh stvari, za katere ga tožite.',
        15: 'Ne, in tudi Herod ne, kajti poslal sem vas k njemu. In glejte, nič smrti vrednega mu ni bilo storjeno.',
        16: 'Kaznoval ga bom torej in ga izpustil.«',
        17: '§ (Kajti nujno jim je moral na praznik nekoga izpustiti.)',
        18: 'In vsi so hkrati zakričali, rekoč: »Proč s tem človekom in izpusti nam Baraba,«',
        19: '(ki je bil vržen v ječo zaradi nekega upora, storjenega v mestu in zaradi umora.)',
        20: 'Pilat jim je torej, voljan izpustiti Jezusa, ponovno spregovoril.',
        21: 'Toda oni so vpili, rekoč: »Križaj ga, križaj ga.«',
        22: 'In tretjič jim je rekel: »Zakaj, kakšno zlo je storil? Nobenega razloga za smrt nisem našel na njem. Kaznoval ga bom torej in ga izpustil.«',
        23: 'Oni pa so bili neposredni z močnimi glasovi in zahtevali, da bi bil križan. In prevladali so glasovi teh ter visokih duhovnikov.',
        24: 'In Pilat je razsodil, da naj bi bilo kakor zahtevajo.',
        25: 'In izpustil jim je tega, ki so ga zahtevali, ki je bil zaradi upora in umora vržen v ječo, toda Jezusa je izročil njihovi volji.',
        26: 'In ko so ga odvedli proč, so prijeli nekega Simona, Cirenčana, ki je prihajal s podeželja in nanj položili križ, da bi ga nosil za Jezusom.',
        27: 'In sledila mu je velika skupina ljudi ter žensk, ki so ga tudi objokovale ter žalovale za njim.',
        28: 'Toda Jezus jim je, ko se je obrnil k njim, rekel: »Hčere jeruzalemske, ne jokajte zaradi mene, temveč jokajte nad seboj in nad svojimi otroki.',
        29: 'Kajti glejte, prihajajo dnevi, v katerih bodo rekli: ›Blagoslovljene so jalove in maternice, ki niso nikoli nosile ter prsi, ki niso nikoli nudile sesanja.‹',
        30: 'Potem bodo začeli govoriti goram: ›Padite na nas;‹ in hribom: ›Pokrijte nas.‹',
        31: 'Kajti če te stvari počnejo z zelenim drevesom, kaj se bo zgodilo s suhim?«',
        32: 'Z njim pa sta bila odvedena tudi dva druga hudodelca, da bi bila usmrčena.',
        33: 'In ko so prišli na kraj, ki se imenuje Kalvarija, so tam križali njega in hudodelca, enega na desni roki, drugega pa na levi.',
        34: 'Potem je Jezus rekel: »Oče, odpusti jim, kajti ne vedo, kaj delajo.« Oni pa so si razdelili njegova oblačila ter metali žrebe.',
        35: 'In ljudje so stoje gledali. Prav tako pa so ga z njimi zasmehovali vladarji, rekoč: »Rešil je druge, naj reši sebe, če je on Kristus, Božji izvoljenec.«',
        36: 'In tudi vojaki so ga zasmehovali, ko so prišli k njemu in mu ponujali kisa',
        37: 'ter rekli: »Če si judovski kralj, reši samega sebe.«',
        38: '§ Nad njim pa je bil tudi nadpis, napisan v črkah grščine in latinščine ter hebrejščine: TO JE JUDOVSKI KRALJ.',
        39: 'Eden izmed hudodelcev, ki sta visela, pa ga je zasmehoval, rekoč: »Če si ti Kristus, reši sebe in naju.«',
        40: 'Vendar mu je drugi odgovoril, ga oštel in rekel: »Ali se ne bojiš Boga, glede na to, da si ti v isti obsodbi?',
        41: 'In midva zares po pravici, kajti prejemava nagrado, primerno svojim dejanjem, toda ta človek ni storil nič narobe.«',
        42: '§ In Jezusu je rekel: »Gospod, spomni se me, ko prideš v svoje kraljestvo.«',
        43: '§ In Jezus mu je rekel: »Resnično, povem ti: ›Danes boš z menoj v raju.‹«',
        44: 'In bilo je okoli šeste ure in bila je tema po vsej zemlji do devete ure.',
        45: 'In sonce je otemnelo in tempeljsko zagrinjalo se je raztrgalo po sredini.',
        46: '§ In ko je Jezus zavpil z močnim glasom, je rekel: »Oče, v tvoje roke izročam svojega duha.« In ko je to izrekel, je izročil duha.',
        47: 'Torej ko je stotnik videl, kaj se je zgodilo, je slavil Boga, rekoč: »Zagotovo je bil to pravičen človek.«',
        48: 'In vsa množica, ki je prišla skupaj k temu prizoru in gledala te stvari, ki so se zgodile, se je tolkla po svojih prsih in se vrnila.',
        49: 'Vsi njegovi znanci in ženske, ki so mu sledili iz Galileje, pa so stali daleč stran in gledali te stvari.',
        50: 'In glej, tam je bil mož, po imenu Jožef, svetovalec. In bil je dober mož ter pravičen',
        51: '(isti ni soglašal z nasvetom in njihovim dejanjem). Bil je iz Arimateje, judovskega mesta, ki je tudi sam pričakoval Božje kraljestvo.',
        52: 'Ta mož je odšel k Pilatu in prosil [za] Jezusovo telo.',
        53: 'In snel ga je ter ga zavil v laneno platno in ga položil v mavzolej, ki je bil vsekan v skalo, v katerega človek še nikoli prej ni bil položen.',
        54: 'In ta dan je bila priprava in približeval se je šabat.',
        55: '§ In tudi ženske, ki so prišle z njim iz Galileje, so potem sledile ter [si] ogledale mavzolej in kako je bilo njegovo telo položeno.',
        56: 'In vrnile so se in pripravile dišave ter mazila in glede na zapoved počivale na šabatni dan.',
    },
    24: {
        1: '§ Torej na prvi dan tedna so zelo zgodaj zjutraj prišle k mavzoleju in nosile dišave, ki so jih pripravile in nekatere druge z njimi.',
        2: 'Našle pa so kamen odvaljen od mavzoleja.',
        3: 'In vstopile so vanj, pa niso našle telesa Gospoda Jezusa.',
        4: 'In pripetilo se je, medtem ko so bile glede tega zelo zmedene, glej, dva moža sta stala poleg njih v sijočih oblekah',
        5: 'in medtem ko so bile prestrašene in so svoje obraze sklonile k zemlji, sta jim rekla: »Zakaj iščete živega med mrtvimi?',
        6: 'Njega ni tukaj, temveč je bil obujen. Spomnite se, kako vam je govoril, ko je bil še v Galileji,',
        7: 'rekoč: ›Sin človekov mora biti izročen v roke grešnih ljudi in biti križan ter tretji dan ponovno vstati.‹«',
        8: 'In spomnile so se njegovih besed',
        9: 'ter se vrnile od mavzoleja in vse te stvari povedale enajsterim ter vsem ostalim.',
        10: 'Bile so Marija Magdalena in Joana in Marija, Jakobova mati ter druge ženske, ki so bile z njimi, ki so te stvari povedale apostolom.',
        11: 'Njihove besede pa so se jim zdele kakor prazno opravljanje in jim niso verjeli.',
        12: 'Potem je vstal Peter in stekel k mavzoleju. In sklonjen dol je zagledal lanene trakove, položene posebej, ter odšel in se v sebi spraševal o tem, kar se je pripetilo.',
        13: 'In glej, dva izmed njih sta tega istega dne odšla proti vasi, z imenom Emavs, ki je bila okoli šestdeset dolžin brazd od Jeruzalema.',
        14: 'In skupaj sta se pogovarjala o vseh teh stvareh, ki so se zgodile.',
        15: 'In pripetilo se je, medtem ko sta se skupaj posvetovala in razpravljala, da se je približal sam Jezus in šel z njima.',
        16: 'Vendar so bile njune oči zadržane, da ga ne bi spoznala.',
        17: 'On pa jima je rekel: »Kakšne vrste pogovori so to, ki jih imata drug z drugim, medtem ko hodita in sta žalostna?«',
        18: 'Eden izmed njiju, ki mu je bilo ime Kleopa, pa mu odgovori in reče: »Ali si ti edini tujec v Jeruzalemu in nisi izvedel stvari, ki so se v teh dneh tam zgodile?«',
        19: 'In rekel jima je: »Katere stvari?« In rekla sta mu: »Glede Jezusa Nazarečana, ki je bil prerok, mogočen v dejanju in besedi, pred Bogom in vsemi ljudmi',
        20: 'in kako so ga visoki duhovniki in naši vladarji izročili, da bi bil obsojen na smrt in ga križali.',
        21: 'Toda mi smo zaupali, da je bil on tisti, ki naj bi odkupil Izraela; in poleg vsega tega je danes tretji dan, odkar so se te stvari zgodile.',
        22: 'Da, in nekatere ženske, prav tako iz naše skupine, ki so bile zgodaj pri mavzoleju, so nas osupnile.',
        23: 'In ko niso našle njegovega telesa, so prišle, rekoč, da so prav tako videle videnje angelov, ki sta rekla, da je bil živ.',
        24: 'In nekateri izmed teh, ki so bili z nami, so odšli k mavzoleju in našli točno takó, kakor so rekle ženske, toda njega niso videli.«',
        25: 'Potem jima je rekel: »Oh bedaka in počasnega srca za verovanje vsega, kar so govorili preroki.',
        26: 'Ali ni moral Kristus pretrpeti te stvari in vstopiti v svojo slavo?«',
        27: 'In začel je pri Mojzesu in vseh prerokih ter jima v vseh pismih pojasnil besede glede njega samega.',
        28: 'In približali so se blizu k vasi, kamor sta šla, on pa je storil, kakor da bo odšel dalje.',
        29: 'Vendar sta ga primorala, rekoč: »Ostani z nama, kajti blizu večera je in dan je davno minil.« In odšel je noter, da ostane z njima.',
        30: 'In pripetilo se je, medtem ko je z njima sedel pri hrani, [da] je vzel kruh in ga blagoslovil in prelomil ter jima dal.',
        31: 'In njune oči so bile odprte in sta ga spoznala, on pa je izginil iz njunega pogleda.',
        32: 'In rekla sta drug drugemu: »Ali ni najino srce gorelo znotraj naju, medtem ko je z nama govoril po poti in medtem ko nama je odpiral pisma?«',
        33: 'In vstala sta še isto uro in se vrnila v Jeruzalem in našla skupaj zbrane enajstere in tiste, ki so bili z njimi,',
        34: 'govoreče: »Gospod je bil resnično obujen in se prikazal Simonu.«',
        35: 'In povedala sta, kakšne stvari so se zgodile na poti in kako sta ga prepoznala po lomljenju kruha.',
        36: 'In ko sta tako govorila, je sam Jezus stal v njihovi sredi in jim reče: »Mir vam bodi.«',
        37: 'Toda bili so prestrašeni in zgroženi in domnevali so, da so videli duha.',
        38: 'Rekel jim je: »Zakaj ste zaskrbljeni? In zakaj v vaših srcih vstajajo misli?',
        39: 'Poglejte moje roke in moja stopala, da sem to jaz sam. Potipajte me in poglejte, kajti duh nima mesa in kosti, kakor vidite, da jih imam jaz.«',
        40: 'In ko je tako govoril, jim je pokazal svoje roke in svoja stopala.',
        41: 'In medtem ko zaradi radosti niso verjeli ter se čudili, jim je rekel: »Imate tukaj kaj hrane?«',
        42: '§ In dali so mu kos pečene ribe in od satovja.',
        43: 'In vzel je to ter pred njimi pojedel.',
        44: 'In rekel jim je: »To so besede, ki sem vam jih govoril, medtem ko sem bil še z vami, da se morajo izpolniti vse stvari, ki so bile glede mene zapisane v Mojzesovi postavi in v prerokih in v psalmih.«',
        45: 'Tedaj jim je odprl njihov razum, da so lahko razumeli pisma',
        46: 'in jim rekel: »Tako je pisano in tako se je Kristusu spodobilo trpeti in tretji dan vstati od mrtvih,',
        47: 'in da bi se kesanje ter odpuščanje grehov oznanjalo v njegovem imenu med vsemi narodi, začenši v Jeruzalemu.',
        48: 'In vi ste priče teh stvari.',
        49: '§ In glejte, nad vas pošiljam obljubo svojega Očeta, toda ostanite v jeruzalemskem mestu, dokler ne boste opremljeni z močjo od zgoraj.«',
        50: 'In odvedel jih je ven, prav do Betanije in povzdignil svoje roke in jih blagoslovil.',
        51: 'In medtem ko jih je blagoslavljal, se je pripetilo, [da] je bil ločen od njih in odnesen gor v nebo.',
        52: 'In oni so ga oboževali in se z veliko radostjo vrnili v Jeruzalem',
        53: '§ in bili so nenehno v templju in hvalili in blagoslavljali Boga. Amen.',
    },
}
